window.LAHANS = {"catalog":[{"kind":"sample","id":"BIZ-101","title":"Business Acumen & Finance for Non-Finance","shortTitle":"Business Acumen & Finance for Non-Finance","category":"Finance & Business","level":"Foundation","duration":"100 menit","summary":"Menghubungkan revenue, COGS, margin, working capital, risiko, dan trade-off lintas fungsi ke keputusan operasional.","audience":"Supervisor, manager, project lead, dan commercial team","roles":["PIC & Manager","Sales & Marketing"],"credential":"Business Acumen badge","assessment":"Business case decision memo","modules":[{"title":"How Lahans creates value"},{"title":"P&L and margin"},{"title":"Cash & working capital"},{"title":"Decision trade-offs"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"COM-101","title":"Effective Workplace Communication","shortTitle":"Effective Workplace Communication","category":"Professional Skills","level":"Foundation","duration":"70 menit","summary":"Memilih kanal, menyusun pesan, mendengar aktif, dan memastikan komunikasi menghasilkan tindakan yang jelas.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Communication Essentials badge","assessment":"Rewrite assignment + scenario quiz","modules":[{"title":"Audience & objective"},{"title":"Clear message structure"},{"title":"Active listening"},{"title":"Chat, email & meeting etiquette"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"ENG-101","title":"Equipment Safety & Basic Care","shortTitle":"Equipment Safety & Basic Care","category":"Engineering & Reliability","level":"Foundation","duration":"80 menit","summary":"Menggunakan basic care, abnormality tagging, isolation awareness, inspection, dan escalation untuk menjaga mesin aman dan andal.","audience":"Operator, technician, engineering, production supervisor, dan maintenance planner","roles":["PIC & Manager","Produksi & Gudang","R&D & Engineering"],"credential":"Equipment Care badge","assessment":"Equipment walkdown checklist","modules":[{"title":"Equipment risk"},{"title":"Clean-inspect-lubricate"},{"title":"Abnormality tagging"},{"title":"Escalation & maintenance record"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"FWB-101","title":"Budgeting, Saving & Financial Goals","shortTitle":"Budgeting, Saving & Financial Goals","category":"Financial Wellbeing","level":"Foundation","duration":"60 menit","summary":"Membuat anggaran realistis, membangun kebiasaan menabung, dan memecah tujuan keuangan menjadi langkah bulanan.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Financial Wellbeing badge 1","assessment":"Personal budget worksheet","modules":[{"title":"Money snapshot"},{"title":"Needs, wants & leakage"},{"title":"Simple budget"},{"title":"Saving automation"},{"title":"Goal tracker"}],"moduleCount":5,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"GWS-101","title":"Google Drive & Shared Drive Essentials","shortTitle":"Google Drive & Shared Drive Essentials","category":"Digital Productivity","level":"Foundation","duration":"55 menit","summary":"Menata folder, hak akses, pencarian, versioning, dan handover file agar informasi kerja mudah ditemukan dan tetap aman.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Digital Workplace badge 1","assessment":"Hands-on folder and access assignment","modules":[{"title":"Drive structure"},{"title":"Sharing & permissions"},{"title":"Search & version history"},{"title":"Shared Drive governance"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"GWS-102","title":"Google Docs Collaboration","shortTitle":"Google Docs Collaboration","category":"Digital Productivity","level":"Foundation","duration":"60 menit","summary":"Membuat dokumen kolaboratif dengan style, komentar, suggestion, version history, template, dan approval yang rapi.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Digital Workplace badge 2","assessment":"Collaborative document assignment","modules":[{"title":"Document structure"},{"title":"Comments & suggestions"},{"title":"Version history"},{"title":"Templates & approvals"}],"moduleCount":4,"prerequisite":"GWS-101","sources":[],"quiz":[]},{"kind":"sample","id":"GWS-103","title":"Google Sheets Fundamentals","shortTitle":"Google Sheets Fundamentals","category":"Digital Productivity","level":"Foundation","duration":"90 menit","summary":"Membangun tabel yang bersih, formula dasar, validasi data, pivot, dan visual ringkas untuk keputusan sehari-hari.","audience":"Seluruh karyawan yang mengolah data","roles":["Seluruh karyawan"],"credential":"Sheets Foundation badge","assessment":"Spreadsheet cleanup and reporting task","modules":[{"title":"Clean tabular data"},{"title":"Core formulas"},{"title":"Validation & protection"},{"title":"Pivot & simple chart"}],"moduleCount":4,"prerequisite":"GWS-101","sources":[],"quiz":[]},{"kind":"sample","id":"LDR-101","title":"Self Leadership & Accountability","shortTitle":"Self Leadership & Accountability","category":"Leadership","level":"Foundation","duration":"75 menit","summary":"Membangun ownership, prioritas, kebiasaan eksekusi, dan akuntabilitas sebelum memimpin orang lain.","audience":"Aspiring leader dan first-time manager","roles":["PIC & Manager"],"credential":"Leadership Foundation badge","assessment":"Reflection + 14-day behavior experiment","modules":[{"title":"Leader mindset"},{"title":"Circle of control"},{"title":"Priorities & commitments"},{"title":"Personal operating system"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"LEG-101","title":"Contract & Compliance Awareness","shortTitle":"Contract & Compliance Awareness","category":"Legal & Compliance","level":"Foundation","duration":"70 menit","summary":"Mengenali scope, obligation, authority, confidentiality, evidence, red flag, approval, dan escalation sebelum membuat komitmen.","audience":"Manager, sales, procurement, project lead, finance, dan contract owner","roles":["PIC & Manager","Procurement","Sales & Marketing","Finance & HR"],"credential":"Contract Awareness badge","assessment":"Contract red-flag scenario","modules":[{"title":"Contract lifecycle"},{"title":"Authority & obligation"},{"title":"Risk clauses"},{"title":"Approval, evidence & escalation"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"ONB-101","title":"Welcome to Lahans","shortTitle":"Welcome to Lahans","category":"Onboarding","level":"Foundation","duration":"35 menit","summary":"Mengenal bisnis Lahans, pelanggan, cara kerja, struktur organisasi, dan pengalaman 30 hari pertama.","audience":"Seluruh karyawan baru","roles":["Seluruh karyawan"],"credential":"Onboarding milestone 1","assessment":"Knowledge check + personal 30-day plan","modules":[{"title":"Lahans at a glance"},{"title":"Customer & value chain"},{"title":"Struktur dan kanal bantuan"},{"title":"30-day success map"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"ONB-102","title":"Culture, Values & Ways of Working","shortTitle":"Culture, Values & Ways of Working","category":"Onboarding","level":"Foundation","duration":"50 menit","summary":"Menerjemahkan nilai perusahaan menjadi perilaku harian, kolaborasi, ownership, dan pengambilan keputusan.","audience":"Seluruh karyawan baru","roles":["Seluruh karyawan"],"credential":"Onboarding milestone 2","assessment":"Scenario-based quiz + manager conversation","modules":[{"title":"Nilai dan perilaku"},{"title":"Ownership in action"},{"title":"Kolaborasi lintas fungsi"},{"title":"Studi kasus budaya"}],"moduleCount":4,"prerequisite":"ONB-101","sources":[],"quiz":[]},{"kind":"sample","id":"ONB-103","title":"Policies, Ethics & Workplace Safety","shortTitle":"Policies, Ethics & Workplace Safety","category":"Onboarding","level":"Foundation","duration":"65 menit","summary":"Kebijakan inti, etika, anti-fraud, perlindungan data, keselamatan kerja, dan jalur speak-up.","audience":"Seluruh karyawan baru","roles":["Seluruh karyawan"],"credential":"Mandatory compliance complete","assessment":"Critical-behavior assessment","modules":[{"title":"Code of conduct"},{"title":"Conflict of interest & anti-fraud"},{"title":"Data & confidentiality"},{"title":"Safety & speak-up"}],"moduleCount":4,"prerequisite":"ONB-102","sources":[],"quiz":[]},{"kind":"sample","id":"ONB-104","title":"Digital Tools: HCMS, Drive, Docs & Sheets","shortTitle":"Digital Tools: HCMS, Drive, Docs & Sheets","category":"Digital Productivity","level":"Foundation","duration":"90 menit","summary":"Praktik memakai HCMS, Google Drive, Docs, dan Sheets dengan struktur folder serta kolaborasi yang aman.","audience":"Seluruh karyawan baru","roles":["Seluruh karyawan"],"credential":"Digital workplace ready","assessment":"Hands-on file and sharing assignment","modules":[{"title":"HCMS essentials"},{"title":"Drive structure & sharing"},{"title":"Docs collaboration"},{"title":"Sheets fundamentals"},{"title":"Data security"}],"moduleCount":5,"prerequisite":"ONB-103","sources":[],"quiz":[]},{"kind":"sample","id":"PM-101","title":"Project Management Fundamentals","shortTitle":"Project Management Fundamentals","category":"Project & Operational Excellence","level":"Foundation","duration":"90 menit","summary":"Mendefinisikan outcome, scope, milestone, owner, risiko, dan ritme komunikasi untuk proyek lintas fungsi.","audience":"Project member, team lead, supervisor, dan manager","roles":["PIC & Manager"],"credential":"Project Foundation badge","assessment":"One-page project charter","modules":[{"title":"Outcome & scope"},{"title":"Plan, owner & milestone"},{"title":"Risk & issue"},{"title":"Stakeholder rhythm"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"qfs","id":"QFS-101","title":"Food Safety & GMP Fundamentals","shortTitle":"Food Safety & GMP","category":"QFS","level":"Foundation","duration":"95 menit","summary":"Fondasi perilaku aman pangan, bahaya utama, higiene, GMP, penyimpanan, traceability, dan respons deviasi untuk semua pekerja.","audience":"Seluruh karyawan; wajib sebelum memasuki area produksi atau gudang.","roles":["Seluruh karyawan","Produksi & Gudang","QA/QC","Procurement","PIC & Manager"],"credential":"Sertifikat operasional Lahans · berlaku 12 bulan","outcomes":["Mengenali bahaya biologis, kimia, fisik, dan alergen.","Menerapkan higiene personal, GMP, FEFO, dan pencegahan kontaminasi silang.","Melaporkan deviasi dan menjaga bukti traceability dengan benar."],"modules":[{"title":"Budaya keamanan pangan","lesson":"Peran setiap orang, speak-up, dan eskalasi bahaya","minutes":10},{"title":"Empat kelompok bahaya","lesson":"Biologis, kimia, fisik, dan alergen","minutes":12},{"title":"GMP & higiene personal","lesson":"Cuci tangan, kesehatan pekerja, pakaian kerja, dan zonasi","minutes":15},{"title":"Cleaning, sanitation & pest","lesson":"Bersih bukan berarti tersanitasi; tanda aktivitas hama","minutes":12},{"title":"Receiving, storage & FEFO","lesson":"Pemeriksaan penerimaan, suhu, status bahan, dan rotasi stok","minutes":12},{"title":"Cross-contamination & allergen","lesson":"Pemisahan, alat, alur orang, dan line clearance","minutes":12},{"title":"Traceability & recall","lesson":"Kode lot, one step back–one step forward, dan simulasi recall","minutes":12},{"title":"Pelaporan deviasi","lesson":"Stop, segregate, protect, report, dan dokumentasikan","minutes":10}],"moduleCount":8,"prerequisite":null,"sources":[{"label":"WHO — Five Keys to Safer Food","type":"Read more","url":"https://www.who.int/publications/i/item/9789241594639"},{"label":"Codex — Codes of Practice","type":"Standar","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/en/"},{"label":"Video: Five Keys to Safer Food","type":"YouTube","url":"https://www.youtube.com/results?search_query=WHO+Five+Keys+to+Safer+Food"}],"quiz":[{"question":"Tindakan pertama saat menemukan bahan tanpa label status adalah…","options":["Tetap dipakai bila tampak baik","Pisahkan dan laporkan","Ganti label sendiri","Campurkan ke lot berikutnya"],"answer":1,"rationale":"Bahan harus di-hold atau dipisahkan agar tidak digunakan sebelum statusnya diverifikasi."},{"question":"Prinsip FEFO berarti…","options":["Barang pertama datang dipakai dulu","Barang termahal dipakai dulu","Masa kedaluwarsa terdekat dipakai dulu","Barang dari pemasok lama dipakai dulu"],"answer":2,"rationale":"FEFO mengutamakan bahan dengan tanggal kedaluwarsa paling dekat."},{"question":"Contoh bahaya fisik adalah…","options":["Salmonella","Residu deterjen","Pecahan kaca","Susu"],"answer":2,"rationale":"Pecahan kaca adalah benda asing yang dapat mencederai konsumen."}],"pretest":[{"question":"Siapa yang bertanggung jawab terhadap keamanan pangan?","options":["Quality saja","Produksi saja","Semua fungsi sesuai perannya","Auditor eksternal"],"answer":2,"rationale":"Food safety adalah tanggung jawab lintas fungsi."},{"question":"Bahan kimia pembersih harus…","options":["Disimpan berlabel sesuai prosedur","Dipindah ke botol minuman","Dicampur sesuka pengguna","Diletakkan dekat bahan baku"],"answer":0,"rationale":"Identitas dan penyimpanan chemical harus terkendali."},{"question":"Karyawan muntah atau diare sebelum shift harus…","options":["Menyembunyikan gejala","Melapor sebelum masuk area","Memakai dua sarung tangan","Bekerja sampai istirahat"],"answer":1,"rationale":"Health reporting melindungi konsumen dan rekan kerja."},{"question":"Status hold berarti…","options":["Bebas digunakan","Menunggu disposition berwenang","Harus langsung dibuang","Label boleh dilepas"],"answer":1,"rationale":"Material hold tidak boleh digunakan sampai ada keputusan."},{"question":"Mock recall menguji…","options":["Desain iklan","Traceability dan pengendalian produk","Kecepatan mesin","Jadwal cuti"],"answer":1,"rationale":"Mock recall menguji kesiapan penelusuran dan pengendalian."}],"posttest":[{"question":"Food safety culture terlihat ketika…","options":["Target selalu didahulukan","Risiko dilaporkan dan ditindaklanjuti","Audit satu-satunya fokus","Quality bekerja sendiri"],"answer":1,"rationale":"Budaya aman mendorong pelaporan dan respons."},{"question":"Alarm detector berulang. Tindakan yang benar?","options":["Bypass alarm","Stop, tahan produk dari titik aman terakhir, dan eskalasi","Lanjut sampai akhir shift","Reset tanpa catatan"],"answer":1,"rationale":"Alarm adalah sinyal kontrol, bukan hambatan produksi."},{"question":"Benda rapuh pecah dekat produk. Tindakan?","options":["Sapu dan lanjut","Stop, isolasi, ikuti breakage response","Tunggu audit","Pindahkan pecahan"],"answer":1,"rationale":"Breakage membutuhkan isolasi, cleaning, inspection, dan release berwenang."},{"question":"Material tanpa status harus…","options":["Dianggap released","Ditahan sampai status dikonfirmasi","Dikirim","Dilabel ulang sendiri"],"answer":1,"rationale":"Status tidak jelas bukan release."},{"question":"Catatan yang benar adalah…","options":["Faktual, kontemporer, memakai identitas sendiri","Diisi dari ingatan","Dapat dihapus","Memakai identitas rekan"],"answer":0,"rationale":"Data integrity membutuhkan catatan faktual dan tertelusur."},{"question":"Temperature excursion ditangani dengan…","options":["Diabaikan bila visual normal","Dicatat, ditahan, dan dinilai pihak berwenang","Label diubah","Produk segera dikirim"],"answer":1,"rationale":"Keputusan memerlukan data, spesifikasi, dan otorisasi."},{"question":"Label salah berbahaya karena…","options":["Hanya mengurangi estetika","Dapat salah menyatakan identitas atau alergen","Membuat produk lebih berat","Tidak terkait food safety"],"answer":1,"rationale":"Mislabeling dapat menyebabkan paparan alergen atau penggunaan yang salah."}],"assignment":["Lakukan speak-up drill: laporkan satu near miss secara faktual menggunakan Stop–Protect–Report–Record dan jalur eskalasi area.","Lakukan hazard walk terkontrol: identifikasi contoh biologis, kimia, fisik, dan alergen serta jelaskan sumber, jalur, dan containment awalnya.","Demonstrasikan health reporting, entry sequence, gowning, hand hygiene, glove change, dan perpindahan zona sesuai prosedur.","Review satu area/equipment: jelaskan urutan cleaning–sanitation–verification, dua chemical control, dua pest red flags, dan release flow.","Petakan satu jalur cross-contamination atau allergen cross-contact dari receiving sampai label, termasuk rework dan changeover.","Periksa receiving/storage secara simulasi: supplier/item, lot, status, kondisi, suhu bila relevan, segregation, dan penerapan FIFO/FEFO.","Demonstrasikan pemeriksaan integritas kemasan, foreign-body control, line clearance, coding, label verification, dan affected-window response.","Lakukan mock trace dan deviation drill: telusuri satu lot ke bahan dan distribusi, lakukan quantity reconciliation, lalu jelaskan complaint/recall/food-defense escalation."],"criticalBehavior":"Tidak menyembunyikan kondisi kesehatan, menggunakan material hold, mengabaikan alarm/breakage, memalsukan catatan, atau melakukan release tanpa kewenangan.","rubric":[{"label":"Higiene & entry","weight":"25%"},{"label":"Hazard recognition","weight":"25%"},{"label":"Material/status control","weight":"25%"},{"label":"Deviation & data integrity","weight":"25%"}],"completion":["Seluruh lesson dan knowledge check selesai.","Post-test minimal 80 dan critical items benar.","OJT dinyatakan competent oleh supervisor/Quality.","Identitas peserta, assessor, scope, dan versi course tercatat."],"remedial":"Skor 70–79: review modul gap. Skor di bawah 70: ulang modul inti dan coaching. Setelah tiga attempt, assessment dikunci sampai coaching selesai.","lessons":[{"intro":"Food safety culture berarti setiap keputusan kerja mempertimbangkan keselamatan konsumen sebelum target, biaya, atau kenyamanan. Near miss dan kondisi tidak aman dilaporkan sebagai kesempatan mencegah insiden.","points":["Semua fungsi bertanggung jawab sesuai perannya—bukan Quality saja.","Laporkan fakta: apa, lokasi, waktu, lot, kondisi, dan tindakan awal.","Gunakan jalur eskalasi berikutnya bila risiko kritis tidak ditanggapi.","Pimpinan menyediakan sumber daya dan melindungi pelaporan yang jujur."],"scenario":"Metal detector memberi alarm berulang menjelang target shift. Respons benar: hentikan proses bila aman, tahan produk sejak pemeriksaan terakhir yang dapat dipercaya, laporkan, dan ikuti investigasi—bukan menonaktifkan alarm.","checks":["Mengapa near miss perlu dilaporkan?","Informasi faktual apa yang disampaikan saat eskalasi?","Sebutkan dua perilaku pimpinan yang memperkuat budaya food safety."]},{"intro":"Bahaya keamanan pangan dikelompokkan menjadi biologis, kimia, fisik, dan alergen. Satu kondisi dapat memiliki lebih dari satu jalur bahaya dan memerlukan beberapa kontrol.","points":["Biologis: patogen dari manusia, bahan, air, lingkungan, atau proses yang tidak terkendali.","Kimia: residu cleaning, pelumas salah, dosis bahan, pestisida, atau kontaminan material.","Fisik: kaca, logam, batu, kayu, plastik keras, staples, atau bagian alat.","Alergen: berpindah lewat bahan, rework, alat, debu, tangan, changeover, dan label."],"scenario":"Ditemukan baut lepas, residu sanitizer, bahan alergen tanpa identitas, dan indikasi bakteri akibat suhu tidak terkendali. Peserta mengklasifikasikan tiap bahaya serta menyebut kontrol awalnya.","checks":["Klasifikasikan empat contoh bahaya di area Anda.","Mengapa visual bersih tidak selalu berarti aman?","Apa tindakan jika status alergen tidak jelas?"]},{"intro":"GMP dan higiene personal mencegah pekerja, pakaian, benda pribadi, dan perilaku menjadi sumber kontaminasi. Sarung tangan tidak menggantikan cuci tangan.","points":["Laporkan muntah, diare, demam, penyakit menular, atau luka terinfeksi sebelum masuk area.","Ikuti urutan gowning, hair/beard cover, alas kaki, masker, dan perlengkapan sesuai zonasi.","Cuci tangan setelah toilet, istirahat, batuk/bersin, ponsel, benda kotor, dan pergantian tugas.","Patuhi aturan perhiasan, makanan/minuman, obat pribadi, ponsel, dan barang terlarang."],"scenario":"Karyawan mengalami diare sebelum shift tetapi lini kekurangan orang. Keputusan penempatan kerja dilakukan pihak berwenang setelah laporan kesehatan—bukan disembunyikan atau ditentukan sendiri.","checks":["Sebutkan empat momen cuci tangan.","Apa yang dilakukan setelah sarung tangan menyentuh ponsel?","Mengapa laporan kesehatan tidak boleh disembunyikan?"]},{"intro":"Cleaning menghilangkan soil dan sisa produk; sanitation menurunkan mikroorganisme setelah permukaan cukup bersih. Parameter berasal dari SOP dan label chemical yang disetujui.","points":["Ikuti urutan persiapan, gross-soil removal, cleaning, rinsing bila perlu, inspection, sanitation, verification, dan release.","Periksa identitas, konsentrasi, alat ukur, contact time, PPE, compatibility, dan penyimpanan chemical.","Pisahkan cleaning tools per zona; tahan alat retak, aus, atau hilang bagian.","Kenali droppings, gnaw marks, webbing, serangga, sarang, bau, dan kemasan rusak sebagai tanda hama."],"scenario":"Sesudah sanitation tercium bau chemical tajam. Jangan mulai proses. Tahan area, laporkan, lakukan tindakan sesuai prosedur, dan verifikasi ulang sebelum release.","checks":["Mengapa cleaning dilakukan sebelum sanitation?","Apa bahaya chemical tanpa label?","Sebutkan tiga tanda aktivitas hama."]},{"intro":"Kontaminasi silang dapat berpindah melalui tangan, sarung tangan, alat, trolley, udara, cairan, alas kaki, kemasan, rework, atau alur orang dan material.","points":["Patuhi batas zona, arah aliran, dan aturan perpindahan alat.","Pisahkan material berdasarkan identitas, status, dan alergen.","Kontrol alergen mencakup receiving, storage, weighing, scheduling, cleaning, line clearance, dan label.","Rework hanya digunakan bila approved, tertelusur, sesuai produk/lot/alergen, dan memenuhi batas resmi."],"scenario":"Scoop bahan alergen ditemukan di area non-alergen. Jangan hanya mengembalikan scoop. Hentikan penggunaan terkait, lindungi material, laporkan, dan lakukan penilaian serta cleaning sesuai prosedur.","checks":["Sebutkan empat jalur kontaminasi silang.","Mengapa label bagian dari allergen control?","Apa syarat minimum penggunaan rework?"]},{"intro":"Receiving dan storage menjaga bahan tetap sesuai identitas, kondisi, status, serta persyaratan penyimpanan sejak diterima sampai digunakan.","points":["Periksa supplier/PO, item, quantity, lot, tanggal, seal, kendaraan, kebersihan, kerusakan, hama, dan suhu bila disyaratkan.","Bedakan quarantine, hold, released, rejected, dan returned.","Ikuti persyaratan suhu, kelembapan, ventilasi, stacking, jarak lantai/dinding, dan compatibility.","FIFO mengikuti urutan penerimaan; FEFO memprioritaskan expiry yang lebih awal."],"scenario":"Data logger menunjukkan temperature excursion selama perjalanan. Material ditahan, waktu/suhu dicatat, lalu dinilai berdasarkan spesifikasi oleh pihak berwenang—visual normal bukan bukti aman.","checks":["Apa yang diperiksa saat receiving?","Bedakan FIFO dan FEFO.","Mengapa material tanpa status harus ditahan?"]},{"intro":"Integritas kemasan, foreign-body control, line clearance, coding, dan label melindungi produk sekaligus memastikan identitas serta keterlacakan.","points":["Periksa retak, bocor, seal lemah, delaminasi, pinhole, deformasi, contamination, closure fit, dan print defect.","Saat changeover, keluarkan atau kendalikan material, dokumen, label, sample, dan produk dari run sebelumnya.","Jaga screen, filter, magnet, detector, brittle-material register, tools, dan fastener.","Alarm atau kerusakan alat deteksi tidak boleh di-bypass."],"scenario":"Dua desain label tercampur pada line. Stop, amankan produk dan material sejak line clearance terakhir, lakukan reconciliation, lalu eskalasi untuk disposition.","checks":["Sebutkan tiga defect kemasan kritis.","Apa tujuan line clearance?","Mengapa alarm detector tidak boleh di-bypass?"]},{"intro":"Traceability menghubungkan supplier, material lot, proses, pemeriksaan, rework, packaging, finished goods, dan distribusi. Respons deviasi mengikuti Stop–Protect–Report–Record.","points":["Stop aktivitas yang memperbesar risiko bila aman dilakukan.","Protect: tahan dan pisahkan produk, material, atau area terdampak.","Report segera melalui jalur resmi; Record fakta secara kontemporer.","Jangan backdate, mengarang hasil, memakai identitas rekan, atau mengubah status tanpa kewenangan."],"scenario":"Customer melaporkan benda asing dengan kode lot jelas. Kumpulkan fakta, lindungi lot terkait, eskalasi, dan jaga bukti—jangan menjanjikan akar masalah sebelum investigasi.","checks":["Apa empat langkah respons deviasi?","Mengapa lot harus terhubung ke distribusi?","Sebutkan dua indikator food-defense concern."]}]},{"kind":"sample","id":"RND-101","title":"Product Development Stage-Gate","shortTitle":"Product Development Stage-Gate","category":"Product & Innovation","level":"Foundation","duration":"95 menit","summary":"Mengubah brief menjadi konsep, formula, trial, risk review, scale-up, dan launch evidence melalui keputusan gate yang jelas.","audience":"R&D, QA, regulatory, marketing, procurement, operations, dan project lead","roles":["Procurement","QA/QC","Sales & Marketing","R&D & Engineering"],"credential":"Innovation Foundation badge","assessment":"Stage-gate case review","modules":[{"title":"Brief & success criteria"},{"title":"Concept and formulation"},{"title":"Trial & risk evidence"},{"title":"Gate review & launch readiness"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"SAL-101","title":"Sales Process & Consultative Selling","shortTitle":"Sales Process & Consultative Selling","category":"Sales & Marketing","level":"Foundation","duration":"95 menit","summary":"Menjalankan sales process Lahans dari persiapan, discovery, product pitch, objection handling, sampai follow-up yang disiplin.","audience":"Sales, sales support, distributor team, dan commercial trainee","roles":["Sales & Marketing"],"credential":"Sales Foundation badge","assessment":"Customer call simulation","modules":[{"title":"Sales process Lahans"},{"title":"Customer discovery"},{"title":"Value-based pitch"},{"title":"Objection & follow-up"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"SCM-101","title":"Supply Chain Lahans End-to-End","shortTitle":"Supply Chain Lahans End-to-End","category":"Supply Chain","level":"Foundation","duration":"85 menit","summary":"Memahami aliran permintaan, bahan, produksi, inventory, distribusi, POD, dan exception dari pemasok sampai pelanggan.","audience":"Supply chain, procurement, warehouse, production, sales operation, dan finance","roles":["Procurement","Produksi & Gudang","Sales & Marketing","Finance & HR"],"credential":"Supply Chain Foundation badge","assessment":"End-to-end case map","modules":[{"title":"Plan-source-make-deliver"},{"title":"Inventory & FEFO"},{"title":"Warehouse controls"},{"title":"Distribution & POD"}],"moduleCount":4,"prerequisite":null,"sources":[],"quiz":[]},{"kind":"sample","id":"COM-201","title":"Public Speaking & Presentation","shortTitle":"Public Speaking & Presentation","category":"Professional Skills","level":"Intermediate","duration":"105 menit","summary":"Merancang alur presentasi, visual sederhana, delivery percaya diri, dan respons efektif terhadap pertanyaan.","audience":"Karyawan yang memimpin presentasi atau briefing","roles":[],"credential":"Presenter badge","assessment":"Five-minute recorded presentation","modules":[{"title":"Audience journey"},{"title":"Story & structure"},{"title":"Visual hierarchy"},{"title":"Voice & body language"},{"title":"Handling Q&A"}],"moduleCount":5,"prerequisite":"COM-101","sources":[],"quiz":[]},{"kind":"sample","id":"DFC-201","title":"Difficult Conversations at Work","shortTitle":"Difficult Conversations at Work","category":"Professional Skills","level":"Intermediate","duration":"90 menit","summary":"Mempersiapkan fakta, mengelola emosi, menyampaikan dampak, dan menyepakati tindak lanjut dalam percakapan sulit.","audience":"Seluruh karyawan, supervisor, dan manager","roles":["Seluruh karyawan","PIC & Manager"],"credential":"Constructive Conversation badge","assessment":"Branching scenario + conversation plan","modules":[{"title":"Facts, story & emotion"},{"title":"Conversation opening"},{"title":"Listen and reframe"},{"title":"Agreement & follow-up"}],"moduleCount":4,"prerequisite":"COM-101","sources":[],"quiz":[]},{"kind":"sample","id":"FWB-102","title":"Emergency Fund & Responsible Debt","shortTitle":"Emergency Fund & Responsible Debt","category":"Financial Wellbeing","level":"Intermediate","duration":"75 menit","summary":"Menentukan dana darurat, membaca biaya utang, memprioritaskan pelunasan, dan mencari bantuan lebih awal.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Financial Wellbeing badge 2","assessment":"Case calculation + recovery plan","modules":[{"title":"Emergency fund target"},{"title":"Interest & total cost"},{"title":"Debt priority"},{"title":"Warning signs"},{"title":"Recovery plan"}],"moduleCount":5,"prerequisite":"FWB-101","sources":[],"quiz":[]},{"kind":"sample","id":"FWB-201","title":"Pinjol, Scams & Personal Data Protection","shortTitle":"Pinjol, Scams & Personal Data Protection","category":"Financial Wellbeing","level":"Intermediate","duration":"65 menit","summary":"Mengenali pinjaman online berisiko, social engineering, penyalahgunaan data, dan langkah aman saat terpapar.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Digital Finance Safety badge","assessment":"Red-flag scenario assessment","modules":[{"title":"Legal vs illegal lending"},{"title":"Total cost & collection risk"},{"title":"Scam red flags"},{"title":"Protecting personal data"},{"title":"Help & reporting"}],"moduleCount":5,"prerequisite":"FWB-102","sources":[],"quiz":[]},{"kind":"sample","id":"FWB-301","title":"Judol Awareness & Financial Harm Prevention","shortTitle":"Judol Awareness & Financial Harm Prevention","category":"Financial Wellbeing","level":"Intermediate","duration":"55 menit","summary":"Memahami pola judi online, tanda bahaya, dampak finansial dan psikologis, serta cara membantu tanpa menghakimi.","audience":"Seluruh karyawan dan people manager","roles":["Seluruh karyawan","PIC & Manager","Finance & HR"],"credential":"Financial Harm Awareness badge","assessment":"Case response + support plan","modules":[{"title":"How gambling hooks work"},{"title":"Financial & wellbeing impact"},{"title":"Warning signs"},{"title":"Supportive conversation"},{"title":"Referral & recovery"}],"moduleCount":5,"prerequisite":"FWB-101","sources":[],"quiz":[]},{"kind":"sample","id":"LDR-201","title":"Leading Through Communication & Feedback","shortTitle":"Leading Through Communication & Feedback","category":"Leadership","level":"Intermediate","duration":"100 menit","summary":"Menetapkan ekspektasi, mendengar aktif, memberi feedback yang jelas, dan membangun psychological safety.","audience":"Supervisor dan manager","roles":["PIC & Manager"],"credential":"People Leader badge 1","assessment":"Recorded feedback role-play","modules":[{"title":"Expectation setting"},{"title":"Active listening"},{"title":"SBI feedback"},{"title":"Psychological safety"},{"title":"Team practice"}],"moduleCount":5,"prerequisite":"LDR-101","sources":[],"quiz":[]},{"kind":"sample","id":"LDR-301","title":"Coaching & Difficult Conversations","shortTitle":"Coaching & Difficult Conversations","category":"Leadership","level":"Intermediate","duration":"120 menit","summary":"Menangani kinerja, konflik, dan percakapan sensitif dengan struktur yang tegas sekaligus manusiawi.","audience":"Supervisor, manager, dan HRBP","roles":["PIC & Manager","Finance & HR"],"credential":"People Leader badge 2","assessment":"Live role-play + observer rubric","modules":[{"title":"Diagnose the gap"},{"title":"GROW coaching"},{"title":"Difficult conversation map"},{"title":"Emotion & resistance"},{"title":"Documentation"}],"moduleCount":5,"prerequisite":"LDR-201","sources":[],"quiz":[]},{"kind":"sample","id":"NEG-201","title":"Practical Negotiation","shortTitle":"Practical Negotiation","category":"Professional Skills","level":"Intermediate","duration":"95 menit","summary":"Negosiasi praktis berbasis kepentingan untuk harga, scope, timeline, dan hubungan kerja jangka panjang.","audience":"Sales, procurement, project lead, dan manager","roles":["PIC & Manager","Procurement","Sales & Marketing"],"credential":"Negotiation Practitioner badge","assessment":"Paired negotiation simulation","modules":[{"title":"Preparation canvas"},{"title":"BATNA & reservation point"},{"title":"Questioning & trading"},{"title":"Closing & documentation"}],"moduleCount":4,"prerequisite":"COM-101","sources":[],"quiz":[]},{"kind":"sample","id":"ONB-105","title":"Role-Ready Checkpoint","shortTitle":"Role-Ready Checkpoint","category":"Onboarding","level":"Intermediate","duration":"45 menit","summary":"Checkpoint hari ke-30 untuk menguji pemahaman peran, SOP utama, tujuan kerja, dan kebutuhan coaching.","audience":"Seluruh karyawan baru dan atasan","roles":["Seluruh karyawan","PIC & Manager"],"credential":"Lahans Onboarding Certificate","assessment":"Role simulation + manager validation","modules":[{"title":"Role clarity"},{"title":"SOP & risk checkpoint"},{"title":"Goal alignment"},{"title":"Manager sign-off"}],"moduleCount":4,"prerequisite":"ONB-104","sources":[],"quiz":[]},{"kind":"sample","id":"OPEX-101","title":"Structured Problem Solving","shortTitle":"Structured Problem Solving","category":"Project & Operational Excellence","level":"Intermediate","duration":"115 menit","summary":"Memecahkan masalah menggunakan problem statement, data, PDCA, 5 Why, fishbone, countermeasure, dan effectiveness check.","audience":"Process owner, supervisor, QA/QC, engineering, dan project lead","roles":["PIC & Manager","QA/QC","R&D & Engineering"],"credential":"Problem Solving Practitioner badge","assessment":"A3-style improvement case","modules":[{"title":"Problem statement"},{"title":"Data & containment"},{"title":"RCA tools"},{"title":"Countermeasure & verification"}],"moduleCount":4,"prerequisite":"PM-101","sources":[],"quiz":[]},{"kind":"qfs","id":"QFS-201","title":"HACCP Awareness","shortTitle":"HACCP Awareness","category":"QFS","level":"Intermediate","duration":"120 menit","summary":"Memahami logika HACCP dari prerequisite programs hingga tujuh prinsip, termasuk CCP, critical limit, monitoring, dan corrective action.","audience":"Produksi, QA/QC, R&D, warehouse, engineering, dan supervisor proses.","roles":["Produksi & Gudang","QA/QC","PIC & Manager"],"credential":"Micro-credential Lahans · HACCP Awareness","outcomes":["Menjelaskan 12 langkah dan 7 prinsip HACCP.","Membedakan bahaya signifikan, control measure, OPRP, dan CCP.","Membaca HACCP plan dan merespons penyimpangan critical limit."],"modules":[{"title":"Fondasi HACCP","lesson":"GHP/GMP, prerequisite programs, dan terminologi","minutes":15},{"title":"Tim, produk & intended use","lesson":"Ruang lingkup, deskripsi produk, konsumen, dan penggunaan","minutes":15},{"title":"Flow diagram","lesson":"Menyusun dan memverifikasi alur proses di lapangan","minutes":15},{"title":"Hazard analysis","lesson":"Severity, likelihood, significant hazard, dan control measure","minutes":20},{"title":"CCP & critical limit","lesson":"Decision logic dan batas yang dapat diukur","minutes":20},{"title":"Monitoring & corrective action","lesson":"Siapa, apa, kapan, bagaimana, dan respons deviasi","minutes":20},{"title":"Verification & records","lesson":"Validasi, verifikasi, review, dan bukti objektif","minutes":15}],"moduleCount":7,"prerequisite":"QFS-101","sources":[{"label":"Codex — General Principles of Food Hygiene","type":"Standar","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/en/"},{"label":"FAO — HACCP resources","type":"Read more","url":"https://www.fao.org/food-safety/resources/tools/details/en/c/1230925/"},{"label":"Video: HACCP seven principles","type":"YouTube","url":"https://www.youtube.com/results?search_query=FAO+HACCP+seven+principles"}],"quiz":[{"question":"Critical limit harus…","options":["Bersifat umum","Terukur atau dapat diamati dengan jelas","Ditentukan setelah deviasi","Sama untuk semua produk"],"answer":1,"rationale":"Critical limit harus membedakan kondisi dapat diterima dan tidak dapat diterima secara jelas."},{"question":"Monitoring CCP terutama bertujuan untuk…","options":["Mengganti audit","Mendeteksi kehilangan kendali tepat waktu","Menentukan harga produk","Menilai pemasok"],"answer":1,"rationale":"Monitoring memberi sinyal saat proses keluar dari critical limit sehingga tindakan cepat dapat dilakukan."},{"question":"Flow diagram HACCP perlu diverifikasi…","options":["Di ruang rapat","Oleh pemasok","Di lokasi proses","Setelah audit eksternal"],"answer":2,"rationale":"Verifikasi lapangan memastikan diagram sesuai kondisi nyata, termasuk rework dan langkah insidental."}],"pretest":[{"question":"Tujuan utama HACCP?","options":["Menguji semua produk akhir","Mengendalikan bahaya signifikan secara sistematis","Menggantikan GMP","Menghilangkan dokumentasi"],"answer":1,"rationale":"HACCP berfokus pada bahaya signifikan."},{"question":"Setiap control measure otomatis CCP?","options":["Ya","Tidak","Hanya bila dipantau Quality","Hanya bila digital"],"answer":1,"rationale":"Penetapan CCP mengikuti hazard analysis."},{"question":"Saat critical limit tidak terpenuhi?","options":["Tunggu hasil akhir","Ubah catatan","Kendalikan proses dan produk","Lanjut sampai shift selesai"],"answer":2,"rationale":"Deviation membutuhkan control dan corrective action."},{"question":"Contoh verification?","options":["Operator membaca suhu","Review berwenang atas record dan penerapan","Menetapkan rasa","Mengubah batas"],"answer":1,"rationale":"Verification memastikan plan diterapkan."},{"question":"Mengapa flow dikonfirmasi di lapangan?","options":["Agar rapi","Agar langkah/rework/delay aktual tidak terlewat","Agar semua jadi CCP","Agar audit singkat"],"answer":1,"rationale":"Diagram harus mencerminkan proses nyata."}],"posttest":[{"question":"Hubungan GHP dan HACCP?","options":["GHP fondasi; HACCP kontrol bahaya signifikan","HACCP mengganti GHP","GHP hanya untuk audit","Tidak berhubungan"],"answer":0,"rationale":"GHP adalah fondasi HACCP."},{"question":"Siapa menyetujui perubahan HACCP plan?","options":["Siapa pun","Pihak berwenang sesuai governance","Operator","Vendor"],"answer":1,"rationale":"Perubahan membutuhkan kompetensi dan otoritas."},{"question":"Monitoring plan memuat…","options":["Apa, metode, frekuensi, penanggung jawab, record","Hanya siapa","Hanya alat","Hanya target"],"answer":0,"rationale":"Monitoring harus lengkap dan dapat diulang."},{"question":"Produk setelah deviation boleh dilepas ketika…","options":["Tampak normal","Shift selesai","Disposition berwenang berbasis bukti","Operator setuju"],"answer":2,"rationale":"Release memerlukan kewenangan dan evidence."},{"question":"Validation menjawab…","options":["Kemampuan ilmiah control measure","Kehadiran training","Warna form","Target produksi"],"answer":0,"rationale":"Validation menilai kemampuan control."},{"question":"Flow berubah karena rework loop. Tindakan?","options":["Abaikan","Change control dan review plan","Catatan pribadi","Tunggu audit"],"answer":1,"rationale":"Perubahan proses memicu review."},{"question":"Record kosong setelah proses. Tindakan?","options":["Isi dari ingatan","Laporkan deviation data integrity","Salin batch lain","Hapus halaman"],"answer":1,"rationale":"Data tidak boleh direkonstruksi sembarang."}],"assignment":["Pilih satu control measure di area dan jelaskan hazard, target, monitoring, record, escalation, dan verification.","Tunjukkan pembuatan record dan koreksi yang benar.","Jelaskan tindakan saat hasil mendekati atau melewati batas.","Selesaikan capstone supplier–delay–missing record."],"criticalBehavior":"Tidak mengubah limit, hasil, status produk, atau disposition tanpa kewenangan.","rubric":[{"label":"Ketepatan konsep","weight":"30%"},{"label":"Penggunaan bukti","weight":"25%"},{"label":"Containment","weight":"25%"},{"label":"Komunikasi & escalation","weight":"20%"}],"completion":["QFS-101 selesai.","Seluruh lesson dan workshop selesai.","Post-test minimal 80 dan critical items benar.","OJT competent pada seluruh critical behavior."],"remedial":"Review modul terkait, coaching HACCP/Quality, lalu gunakan set soal dan kasus berbeda.","lessons":[{"intro":"HACCP tidak menggantikan GMP atau program prasyarat. Hygiene, sanitation, pest, supplier, maintenance, allergen, traceability, dan kompetensi harus berfungsi sebagai fondasi.","points":["Hazard adalah agen biologis, kimia, fisik, atau alergen.","Hazard analysis menilai kemungkinan, severity, signifikansi, dan control measure.","Kriteria risiko mengikuti metode resmi Lahans.","Fondasi yang lemah menghasilkan control plan yang tidak realistis."],"scenario":"Kelompokkan contoh menjadi hazard, kondisi, penyebab, konsekuensi, atau control measure.","checks":["Mengapa GHP diperlukan sebelum HACCP?","Apa beda hazard dan risk?","Siapa menetapkan kriteria signifikansi?"]},{"intro":"Lima preliminary steps memastikan analisis dilakukan oleh tim yang kompeten dan berdasarkan produk serta proses aktual.","points":["Bentuk tim HACCP dengan pengetahuan proses dan pangan.","Deskripsikan bahan, proses, kemasan, storage, distribusi, masa simpan, dan intended use.","Susun flow diagram termasuk holding, rework, outsourcing, waste interface, dan delay.","Konfirmasi diagram di lapangan dan perbarui saat proses berubah."],"scenario":"Temukan langkah yang hilang pada flow proses minuman botol generik.","checks":["Informasi apa yang masuk deskripsi produk?","Mengapa intended use penting?","Mengapa flow diagram diverifikasi di lokasi?"]},{"intro":"Tujuh prinsip mencakup hazard analysis, penetapan CCP, critical limit, monitoring, corrective action, verification, dan records.","points":["CCP ditetapkan melalui pendekatan yang disetujui—tidak setiap control measure adalah CCP.","Critical limit harus terukur/dapat diamati, tervalidasi, dan membedakan acceptable dari unacceptable.","Monitoring menetapkan apa, metode, waktu/frekuensi, siapa, dan record.","Deviation response mengembalikan kendali serta melindungi produk terdampak."],"scenario":"Critical limit tidak terpenuhi. Tentukan kontrol proses, produk terdampak, evidence, dan pihak pemberi disposition.","checks":["Apa ciri critical limit yang baik?","Apa isi monitoring plan?","Apa beda verification dan validation?"]},{"intro":"Data monitoring harus kontemporer, terbaca, memakai alat dan identitas yang benar, serta dikoreksi sesuai prosedur.","points":["Jangan mengarang, backdate, menyalin hasil, atau mengisi tanpa observasi.","Hasil masih di dalam batas dapat menunjukkan tren menuju loss of control.","Ikuti escalation rule dan jangan mengubah setting di luar kewenangan.","Jaga identitas produk serta record selama penilaian."],"scenario":"Tiga hasil berturut-turut mendekati critical limit. Tentukan data tambahan, pihak yang diberi tahu, dan tindakan yang diizinkan.","checks":["Mengapa tren penting?","Apa risiko backdating?","Siapa boleh mengubah parameter?"]},{"intro":"HACCP plan ditinjau berkala dan saat perubahan material atau informasi bahaya baru muncul.","points":["Pemicu review: bahan, supplier, formula, equipment, layout, parameter, packaging, storage, distribusi, intended use, regulasi, dan hazard baru.","Personel awareness tidak mengubah HACCP plan sendiri.","Perannya menjalankan control, membuat record akurat, dan melaporkan deviasi/perubahan.","Verification mencakup record review, observasi, kalibrasi, sampling, audit, dan reanalysis."],"scenario":"Supplier berubah, ada delay sebelum filling, dan record kosong. Susun pertanyaan hazard, containment, serta bagian plan yang ditinjau.","checks":["Kapan plan direview?","Apa peran operator awareness?","Sebutkan tiga aktivitas verification."]},{"intro":"Workshop menerapkan konsep HACCP pada kasus lintas fungsi dan menilai kualitas bukti sebelum keputusan.","points":["Definisikan affected scope.","Pisahkan fakta, dugaan, dan bukti yang masih dibutuhkan.","Pilih containment yang tidak merusak evidence.","Komunikasikan escalation tanpa mengubah disposition."],"scenario":"Kasus minuman siap konsumsi: supplier baru, delay filling, dan monitoring record kosong.","checks":["Apa fakta yang tersedia?","Apa bukti yang perlu diminta?","Bagaimana melindungi produk?"]},{"intro":"Records dan verification menunjukkan bahwa HACCP plan dijalankan serta efektif, bukan hanya tertulis.","points":["Record harus aktual, terbaca, tertelusur, dan direview pihak berwenang.","Verification independen dari monitoring sejauh praktis.","Validation menilai kemampuan ilmiah/teknis control measure.","Reanalysis dilakukan saat perubahan atau bukti menunjukkan plan mungkin tidak memadai."],"scenario":"Review tiga record: satu lengkap, satu backdated, dan satu tanpa identitas alat. Tentukan status serta tindak lanjut.","checks":["Apa ciri record dapat dipercaya?","Siapa mereview record?","Kapan reanalysis dibutuhkan?"]}]},{"kind":"qfs","id":"QFS-202","title":"Halal Assurance","shortTitle":"Halal Assurance","category":"QFS","level":"Intermediate","duration":"105 menit","summary":"Kesadaran Sistem Jaminan Produk Halal: bahan kritis, persetujuan pemasok, fasilitas, proses, traceability, dan pengendalian perubahan.","audience":"QA/QC, procurement, warehouse, produksi, R&D, regulatory, dan PIC halal.","roles":["Produksi & Gudang","QA/QC","Procurement","PIC & Manager"],"credential":"Micro-credential Lahans · Halal Assurance","outcomes":["Mengidentifikasi titik kritis halal pada bahan, fasilitas, dan proses.","Memeriksa bukti halal pemasok sebelum perubahan bahan disetujui.","Menjaga traceability dan menangani ketidaksesuaian halal."],"modules":[{"title":"Fondasi halal & tanggung jawab","lesson":"Kebijakan, peran, dan budaya kepatuhan","minutes":15},{"title":"Bahan kritis","lesson":"Asal bahan, processing aid, flavor, dan dokumen pendukung","minutes":20},{"title":"Supplier & change control","lesson":"Approval, daftar bahan, dan larangan substitusi tanpa izin","minutes":18},{"title":"Fasilitas & proses","lesson":"Pemisahan, cleaning, penyimpanan, dan transportasi","minutes":18},{"title":"Traceability halal","lesson":"Pencocokan bahan, batch, formula, dan produk jadi","minutes":17},{"title":"Audit & ketidaksesuaian","lesson":"Bukti, containment, koreksi, dan pelaporan","minutes":17}],"moduleCount":6,"prerequisite":"QFS-201","sources":[{"label":"BPJPH — Informasi sertifikasi halal","type":"Regulasi","url":"https://bpjph.halal.go.id/"},{"label":"Halal Indonesia — Portal layanan","type":"Read more","url":"https://ptsp.halal.go.id/"},{"label":"Video edukasi halal BPJPH","type":"YouTube","url":"https://www.youtube.com/results?search_query=BPJPH+jaminan+produk+halal"}],"quiz":[{"question":"Pemasok menawarkan bahan pengganti yang spesifikasinya sama. Apa yang dilakukan?","options":["Langsung gunakan","Gunakan untuk trial produksi","Tahan sampai approval dan bukti halal diverifikasi","Campur dengan stok lama"],"answer":2,"rationale":"Perubahan bahan atau pemasok harus melalui change control dan verifikasi status halal."},{"question":"Traceability halal menghubungkan…","options":["Hanya produk jadi","Bahan, pemasok, batch, formula, dan produk","Hanya invoice","Hanya sertifikat"],"answer":1,"rationale":"Integritas halal memerlukan keterlacakan end-to-end, bukan satu dokumen terpisah."},{"question":"Jika dokumen halal bahan kedaluwarsa…","options":["Abaikan jika bahan biasa dipakai","Tahan dan eskalasi sesuai prosedur","Perbarui tanggal sendiri","Gunakan lebih cepat"],"answer":1,"rationale":"Status harus diverifikasi sebelum bahan dilepas untuk digunakan."}],"pretest":[{"question":"Sertifikat produk membuat bahan baru otomatis boleh?","options":["Ya","Tidak; perubahan harus approved","Ya bila supplier lama","Ya bila sedikit"],"answer":1,"rationale":"Bahan baru tetap melalui approval."},{"question":"Siapa menjaga kehalalan?","options":["Penyelia saja","Semua fungsi terkait","Marketing","Auditor"],"answer":1,"rationale":"SJPH lintas fungsi."},{"question":"Status bahan tidak jelas?","options":["Gunakan","Tahan, pisahkan, eskalasi","Ganti label","Campur"],"answer":1,"rationale":"Status harus dikonfirmasi."},{"question":"Perubahan formula?","options":["Setelah approval dan evaluasi","Jalankan dulu","Tidak perlu","Vendor memutuskan"],"answer":0,"rationale":"Perubahan dinilai sebelum implementasi."},{"question":"Traceability halal menghubungkan?","options":["Invoice","Bahan, lot, proses, produk, distribusi","Produk akhir","Sertifikat"],"answer":1,"rationale":"Traceability harus end-to-end."}],"posttest":[{"question":"Fungsi SJPH?","options":["Promosi","Menjaga kesinambungan PPH","Mengganti GMP","Mengurangi record"],"answer":1,"rationale":"SJPH menjaga konsistensi PPH."},{"question":"Bahan boleh digunakan ketika…","options":["Supplier terkenal","Identitas/status sesuai approved list","Harga disetujui","Kemasan bersih"],"answer":1,"rationale":"Approval dan identitas wajib cocok."},{"question":"Produsen bahan berubah dengan kode sama?","options":["Abaikan","Evaluasi change control","Catat setelah produksi","Operator memutuskan"],"answer":1,"rationale":"Sumber material merupakan bagian status."},{"question":"Segregasi berlaku pada…","options":["Gudang","Seluruh scope relevan","Produk jadi","Dokumen"],"answer":1,"rationale":"Segregasi end-to-end."},{"question":"Rework boleh digunakan bila…","options":["Terlihat baik","Approved dan tertelusur","Jumlah sedikit","Warna sama"],"answer":1,"rationale":"Rework memerlukan approval dan traceability."},{"question":"Logo halal boleh digunakan…","options":["Pada semua produk","Sesuai scope dan artwork approved","Saat marketing meminta","Pada trial"],"answer":1,"rationale":"Penggunaan logo harus sesuai approval."},{"question":"Bukti halal tidak dapat dipercaya. Tindakan?","options":["Release","Hold dan eskalasi","Ganti dokumen","Gunakan stok"],"answer":1,"rationale":"Produk dilindungi sampai status jelas."}],"assignment":["Pilih satu bahan dan tunjukkan hubungan approved list, dokumen, receiving lot, batch, serta produk.","Demonstrasikan pemeriksaan status bahan saat receiving.","Identifikasi dua titik risiko segregasi atau line clearance.","Selesaikan case flavour baru dan change control."],"criticalBehavior":"Tidak menggunakan bahan, formula, fasilitas, label, atau logo di luar approval; tidak mengganti identitas untuk melewati hold.","rubric":[{"label":"Keputusan hold","weight":"25%"},{"label":"Kelengkapan bukti","weight":"30%"},{"label":"Traceability","weight":"25%"},{"label":"Komunikasi & escalation","weight":"20%"}],"completion":["QFS-101 selesai.","Seluruh lesson dan case workshop selesai.","Post-test minimal 80.","Assignment divalidasi Penyelia Halal/Quality."],"remedial":"Review learning gap, coaching Penyelia Halal, lalu reassessment menggunakan bahan dan skenario berbeda.","lessons":[{"intro":"Sertifikat halal adalah bukti formal; konsistensi dijaga melalui Sistem Jaminan Produk Halal yang mengendalikan bahan, proses, produk, sumber daya, dan prosedur.","points":["Pimpinan menetapkan komitmen dan sumber daya.","Penyelia Halal mengawasi pelaksanaan.","Fungsi terkait menjalankan kontrol sesuai peran.","Setiap potensi dampak terhadap integritas halal wajib dilaporkan."],"scenario":"Petakan peran Procurement, R&D, Receiving, Production, Warehouse, Marketing, dan Logistics pada satu produk.","checks":["Apa tujuan SJPH?","Siapa menjaga integritas halal?","Apa yang harus dilaporkan?"]},{"intro":"Gunakan hanya bahan dalam daftar approved yang sesuai identitas, produsen, fasilitas, spesifikasi, dan bukti pendukung.","points":["Nama dagang sama tidak membuktikan sumber/status sama.","Receiving memverifikasi identitas, lot, dokumen, kondisi, dan status.","Bahan atau supplier baru masuk change control sebelum digunakan.","Perubahan fasilitas supplier juga harus dinilai."],"scenario":"Supplier mengganti fasilitas produksi tetapi kode material sama. Tahan bahan dan minta bukti sebelum approval.","checks":["Apa yang diperiksa saat receiving?","Mengapa kode sama belum cukup?","Kapan change control dilakukan?"]},{"intro":"Proses Produk Halal mencakup penyediaan bahan, pengolahan, storage, packaging, distribusi, penjualan, dan penyajian sesuai scope.","points":["Alur, tempat, alat, kendaraan, wadah, dan cleaning mencegah pencampuran yang tidak diizinkan.","Segregasi berlaku sepanjang alur, bukan hanya gudang.","Rework harus approved, beridentitas, tertelusur, dan sesuai produk/status.","Line clearance mencegah material, label, dan dokumen tertinggal."],"scenario":"Temukan titik cross-contact halal pada shared trolley, rework, dan changeover.","checks":["Apa scope PPH?","Apa syarat rework?","Apa tujuan line clearance?"]},{"intro":"Produk dan label harus sesuai approval; traceability menghubungkan bahan approved hingga distribusi.","points":["Nama, desain, komposisi, klaim, dan logo halal tidak boleh keluar scope.","Hubungkan purchase, bukti status, receiving lot, batch, label, finished goods, dan shipment.","Informasi yang tidak dipercaya menyebabkan hold sampai keputusan.","Perubahan formula dan artwork dinilai sebelum implementasi."],"scenario":"Audit satu batch generik: cocokkan daftar approved, receiving lot, batch record, label, dan shipment.","checks":["Apa yang dihubungkan traceability halal?","Kapan logo boleh digunakan?","Apa tindakan saat informasi tidak lengkap?"]},{"intro":"Ketidaksesuaian halal ditangani dengan stop, hold, segregation, reporting, evidence preservation, dan disposition berwenang.","points":["Jangan menyembunyikan penggunaan bahan atau mengganti identitas.","Audit internal menilai penerapan serta bukti.","Kaji ulang melihat perubahan, temuan, dan efektivitas tindakan.","Pelatihan, approval, production, cleaning, traceability, complaint, dan CAPA dipelihara."],"scenario":"Flavour baru tiba dengan nama serupa dan sertifikat berbeda. Buat keputusan hold, daftar bukti, approval flow, dan komunikasi produksi.","checks":["Apa respons awal penyimpangan?","Bukti apa yang dibutuhkan audit?","Siapa memberi disposition?"]},{"intro":"Case workshop menguji keputusan lintas fungsi ketika jadwal produksi bertabrakan dengan ketidakjelasan status halal.","points":["Pisahkan kebutuhan bisnis dari keputusan kepatuhan.","Tentukan material dan produk yang ditahan.","Buat daftar dokumen serta pemilik approval.","Rancang traceability plan sebelum penggunaan."],"scenario":"Produksi dijadwalkan hari ini, tetapi flavour baru belum tercantum pada daftar approved.","checks":["Apa keputusan pertama?","Siapa diinformasikan?","Apa larangan sebelum approval?"]}]},{"kind":"qfs","id":"QFS-203","title":"BPOM, Label & Traceability","shortTitle":"BPOM & Traceability","category":"QFS","level":"Intermediate","duration":"110 menit","summary":"Kontrol registrasi pangan olahan, elemen label, klaim, kode produksi, distribusi, traceability, dan mock recall.","audience":"Regulatory, QA/QC, marketing, R&D, produksi, warehouse, sales operation, dan distribution.","roles":["Produksi & Gudang","QA/QC","Procurement","PIC & Manager"],"credential":"Micro-credential Lahans · Label & Traceability","outcomes":["Mengenali elemen label yang wajib dikendalikan dan risiko klaim.","Menghubungkan bahan, proses, lot produk, dan distribusi.","Melaksanakan mock recall dan menghitung rekonsiliasi produk."],"modules":[{"title":"Registrasi & product identity","lesson":"Peran BPOM, nomor izin edar, dan kontrol perubahan","minutes":16},{"title":"Elemen label","lesson":"Nama, komposisi, alergen, netto, kedaluwarsa, dan produsen","minutes":20},{"title":"Klaim & artwork control","lesson":"Persetujuan lintas fungsi dan version control","minutes":18},{"title":"Kode lot & production record","lesson":"Batch genealogy dan keterbacaan kode","minutes":18},{"title":"Traceability distribusi","lesson":"One step back–one step forward dan bukti pengiriman","minutes":18},{"title":"Mock recall","lesson":"Tim, komunikasi, rekonsiliasi, waktu, dan lesson learned","minutes":20}],"moduleCount":6,"prerequisite":"QFS-202","sources":[{"label":"BPOM — Registrasi Pangan Olahan","type":"Regulasi","url":"https://registrasipangan.pom.go.id/"},{"label":"JDIH BPOM — Peraturan","type":"Read more","url":"https://jdih.pom.go.id/"},{"label":"Codex — Food Labelling texts","type":"Standar","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/standards/en/"}],"quiz":[{"question":"Artwork label hendak diubah. Kontrol terpenting adalah…","options":["Langsung cetak sampel","Persetujuan lintas fungsi dan version control","Hanya persetujuan desain","Menghabiskan kemasan lama tanpa review"],"answer":1,"rationale":"Perubahan label dapat memengaruhi kepatuhan, alergen, klaim, dan izin edar sehingga wajib dikendalikan."},{"question":"Traceability yang baik memungkinkan perusahaan…","options":["Menebak lot","Menghubungkan pemasok, batch, dan pelanggan","Menghilangkan semua risiko","Mengganti kode produksi"],"answer":1,"rationale":"Tujuan utamanya adalah menelusuri asal dan tujuan lot secara cepat dan akurat."},{"question":"Mock recall perlu mengevaluasi…","options":["Warna kemasan","Kecepatan, akurasi, dan rekonsiliasi jumlah","Jumlah rapat","Harga distribusi"],"answer":1,"rationale":"Efektivitas recall diukur dari kemampuan menemukan lot dan merekonsiliasi jumlah dalam target waktu."}],"pretest":[{"question":"Artwork boleh diubah tanpa review?","options":["Ya","Tidak; change control","Ya bila warna","Ya bila customer"],"answer":1,"rationale":"Artwork dikendalikan."},{"question":"BPOM RI MD menunjukkan…","options":["Produksi dalam negeri sesuai izin","Otomatis halal","Bebas audit","Nama merek"],"answer":0,"rationale":"MD terkait produk dalam negeri."},{"question":"Label salah di line?","options":["Lanjut","Stop, amankan, rekonsiliasi, eskalasi","Tutup stiker","Buang record"],"answer":1,"rationale":"Mislabeling membutuhkan containment."},{"question":"Traceability minimum?","options":["Master, material, lot, label, produk, distribusi","Invoice","Operator","Foto"],"answer":0,"rationale":"Traceability end-to-end."},{"question":"Klaim label harus…","options":["Bebas dibuat","Sesuai bukti, ketentuan, approval","Tidak perlu konsisten","Di luar change control"],"answer":1,"rationale":"Klaim harus dapat dipertanggungjawabkan."}],"posttest":[{"question":"Tujuan registrasi pangan?","options":["Mengganti kontrol","Mendukung persyaratan sebelum beredar","Menentukan harga","Menghapus label"],"answer":1,"rationale":"Registrasi bagian kontrol pre-market."},{"question":"Artwork baru boleh dipakai setelah…","options":["Dikirim agency","Review, approval, release","Disukai Sales","Dicetak vendor"],"answer":1,"rationale":"Artwork dikendalikan."},{"question":"Risiko mislabeling paling serius?","options":["Warna beda","Alergen atau identitas salah","Dekorasi bergeser","Gloss berkurang"],"answer":1,"rationale":"Dapat berdampak keselamatan."},{"question":"Kode tidak terbaca?","options":["Lanjut","Kendalikan, hold, eskalasi","Tulis manual","Abaikan"],"answer":1,"rationale":"Coding gap perlu containment."},{"question":"Change control untuk…","options":["Perubahan berpotensi berdampak approval/proses/label","Hanya vendor","Produk baru","Harga"],"answer":0,"rationale":"Dampak lintas dokumen dinilai."},{"question":"Line reconciliation membantu…","options":["Mencegah mix-up label","Menentukan rasa","Mengurangi training","Mengganti traceability"],"answer":0,"rationale":"Reconciliation menguji selisih dan mix-up."},{"question":"Label approved tidak sama dengan produk aktual?","options":["Tetap benar","NC yang dikendalikan dan diinvestigasi","Perbaiki setelah distribusi","Tak perlu dicatat"],"answer":1,"rationale":"Produk aktual harus sesuai approval."}],"assignment":["Pilih satu SKU dan tunjukkan hubungan product master, artwork version, lot code, serta finished-goods record.","Demonstrasikan line clearance atau label verification.","Jelaskan tindakan label mismatch dan affected window.","Selesaikan label clinic serta mock trace."],"criticalBehavior":"Tidak menggunakan artwork, kode, klaim, atau label yang belum released; tidak membuat disposition di luar kewenangan.","rubric":[{"label":"Checklist","weight":"30%"},{"label":"Identifikasi risiko","weight":"30%"},{"label":"Containment","weight":"25%"},{"label":"Escalation","weight":"15%"}],"completion":["QFS-101 selesai.","Seluruh lesson dan clinic selesai.","Post-test minimal 80.","OJT competent pada critical behavior."],"remedial":"Review modul, coaching Regulatory/Quality, perbaiki clinic, lalu kerjakan set soal berbeda.","lessons":[{"intro":"Registrasi membantu memastikan pangan olahan memenuhi persyaratan keamanan, mutu, gizi, label, dan ketentuan terkait sebelum beredar.","points":["Identitas dikendalikan meliputi NIE/PB-UMKU, jenis, merek, komposisi, proses, kemasan, berat, dan fasilitas.","Istilah dan ketentuan dapat berubah; gunakan portal resmi terbaru.","Kesamaan merek tidak berarti semua varian memiliki approval sama.","Keputusan regulatori berada pada pihak berwenang."],"scenario":"Bandingkan dua varian bermerek sama dan identifikasi elemen identity master yang berbeda.","checks":["Mengapa registrasi diperlukan?","Apa yang membentuk identitas produk?","Siapa menetapkan jalur registrasi?"]},{"intro":"Label harus benar, tidak menyesatkan, terbaca, dan sesuai kategori serta approval.","points":["Kontrol nama, daftar bahan, netto, produsen/importir, lot, kedaluwarsa, izin edar, alergen, dan informasi relevan.","Artwork master, proof, printer setting, dan sample line dikendalikan.","Checklist menemukan gap; Regulatory menyimpulkan status legal.","Informasi tidak boleh mudah lepas atau rusak selama penggunaan wajar."],"scenario":"Lakukan label clinic pada contoh tanpa menyatakan kesimpulan legal di luar kewenangan.","checks":["Apa elemen utama label?","Mengapa keterbacaan penting?","Apa batas peran peserta?"]},{"intro":"Formula, komposisi, alergen, nilai gizi, klaim, nama, gambar, instruksi, shelf life, dan kode harus selaras.","points":["Perubahan bahan/supplier dapat memengaruhi beberapa dokumen.","Perubahan proses, fasilitas, kemasan, artwork, berat, klaim, atau shelf life masuk change control.","Evaluasi dilakukan sebelum implementasi.","Regulatory menentukan kebutuhan registrasi/variasi."],"scenario":"Satu bahan diganti dan Marketing ingin mempertahankan klaim lama. Petakan dokumen yang harus direview.","checks":["Apa arti alignment lintas data?","Kapan change control dimulai?","Siapa menentukan kebutuhan variasi?"]},{"intro":"Line clearance, reconciliation, dan coding mencegah material label bercampur serta menjaga keterlacakan.","points":["Kendalikan label, film, carton, dokumen, dan sample sebelum start/changeover.","Verifikasi item, version, lot, tanggal, code, dan quantity.","Selisih quantity mengikuti prosedur.","Jangan mengubah printer setting atau disposition tanpa kewenangan."],"scenario":"Dua desain label ditemukan pada line. Tentukan stop point, affected window, dan rekonsiliasi.","checks":["Apa tujuan reconciliation?","Apa yang diverifikasi saat start?","Apa tindakan saat kode tidak terbaca?"]},{"intro":"Traceability menghubungkan supplier/material lot, batch proses, inspection, packaging lot, finished goods, storage, shipment, dan customer.","points":["One step back dan one step forward adalah minimum, bukan seluruh kemampuan sistem.","Mock trace menguji kecepatan, kelengkapan, rekonsiliasi, dan kualitas bukti.","Complaint benda asing, alergen, mislabel, tampering, atau sakit masuk kanal resmi segera.","Affected lot tidak boleh ditebak."],"scenario":"Sebagian produk salah label sudah di gudang. Susun affected window, hold, data, komunikasi, dan disposition flow.","checks":["Apa yang dihubungkan traceability?","Apa ukuran mock trace?","Kapan complaint dieskalasi?"]},{"intro":"Capstone label clinic menggabungkan artwork control, line evidence, traceability, dan containment.","points":["Pisahkan material label dan finished goods terdampak.","Kumpulkan master, proof, printer record, reconciliation, dan shipment status.","Tentukan siapa yang dapat memberi disposition.","Catat keputusan serta evidence tanpa mengubah record asli."],"scenario":"Dua desain label digunakan dan sebagian produk pindah gudang.","checks":["Apa yang di-hold?","Bukti apa yang dibutuhkan?","Bagaimana menentukan affected window?"]}]},{"kind":"qfs","id":"QFS-204","title":"Sanitation, Pest & Allergen","shortTitle":"Sanitation & Allergen","category":"QFS","level":"Intermediate","duration":"115 menit","summary":"Pengendalian cleaning dan sanitation, bahan kimia, verifikasi, pest management, alergen, changeover, dan line clearance.","audience":"Sanitation, produksi, QA/QC, warehouse, engineering, dan pest-control coordinator.","roles":["Produksi & Gudang","QA/QC","PIC & Manager"],"credential":"Micro-credential Lahans · Hygiene Control","outcomes":["Membedakan cleaning, sanitation, validation, dan verification.","Menggunakan bahan kimia dan alat cleaning sesuai SSOP.","Mengendalikan hama dan alergen dari penerimaan hingga changeover."],"modules":[{"title":"Cleaning vs sanitation","lesson":"Tujuan, urutan, dan risiko biofilm","minutes":16},{"title":"SSOP yang dapat dieksekusi","lesson":"Siapa, apa, kapan, bagaimana, dan safety","minutes":18},{"title":"Chemical control","lesson":"Label, konsentrasi, waktu kontak, penyimpanan, dan verifikasi","minutes":20},{"title":"Integrated pest management","lesson":"Exclusion, monitoring, trend, dan eskalasi","minutes":18},{"title":"Allergen map & segregation","lesson":"Penerimaan, penyimpanan, alat, rework, dan label","minutes":20},{"title":"Changeover & line clearance","lesson":"Urutan produksi, pemeriksaan, swab, dan pelepasan line","minutes":23}],"moduleCount":6,"prerequisite":"QFS-203","sources":[{"label":"FDA — Food Allergies","type":"Read more","url":"https://www.fda.gov/food/food-labeling-nutrition/food-allergies"},{"label":"Codex — Food Hygiene","type":"Standar","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/en/"},{"label":"Video: food allergen controls","type":"YouTube","url":"https://www.youtube.com/results?search_query=food+allergen+control+manufacturing"}],"quiz":[{"question":"Sesudah cleaning, permukaan masih terlihat residu. Apa keputusan yang benar?","options":["Lanjut sanitasi","Ulangi cleaning sebelum sanitasi","Mulai produksi","Tutup dengan kain"],"answer":1,"rationale":"Sanitizer tidak menggantikan pembersihan; residu organik dapat menurunkan efektivitas sanitasi."},{"question":"Temuan kotoran hama harus…","options":["Disapu tanpa catatan","Didokumentasikan, diamankan, dan dieskalasi","Disemprot sembarang","Ditunggu sampai audit"],"answer":1,"rationale":"Bukti perlu dijaga untuk penilaian risiko, tindakan koreksi, dan analisis tren."},{"question":"Line clearance alergen dilakukan untuk…","options":["Mempercepat changeover","Mencegah carry-over bahan atau label","Mengurangi jumlah operator","Mengganti verifikasi"],"answer":1,"rationale":"Line clearance memastikan residu, bahan, kemasan, dan label batch sebelumnya sudah terkendali."}],"pretest":[{"question":"Cleaning dan sanitation sama?","options":["Ya","Tidak","Hanya beda nama","Sanitation dulu"],"answer":1,"rationale":"Fungsinya berbeda."},{"question":"Chemical ke botol tanpa label?","options":["Boleh","Tidak","Boleh bila warna","Boleh bila supervisor tahu"],"answer":1,"rationale":"Identitas wajib jelas."},{"question":"Tanda hama?","options":["Pindah perangkap","Lindungi produk dan lapor","Semprot sendiri","Tunggu audit"],"answer":1,"rationale":"Jaga evidence dan eskalasi."},{"question":"Cross-contact melalui…","options":["Alat, debu, rework, tangan, label","Label saja","Produk akhir","Supplier saja"],"answer":0,"rationale":"Banyak jalur cross-contact."},{"question":"Pre-op gagal?","options":["Release sementara","Hold, koreksi, verify ulang","Tutup temuan","Mulai tanpa catatan"],"answer":1,"rationale":"Area gagal tidak boleh release."}],"posttest":[{"question":"Tujuan cleaning?","options":["Menghilangkan soil","Mengganti sanitation","Menambah aroma","Menghapus record"],"answer":0,"rationale":"Cleaning menghilangkan soil."},{"question":"Sanitation dilakukan pada…","options":["Permukaan yang telah dibersihkan","Permukaan penuh residu","Produk jadi","Karton"],"answer":0,"rationale":"Soil menurunkan efektivitas."},{"question":"Contact time chemical…","options":["Dipendekkan","Ikuti label/prosedur","Ditentukan operator","Tidak penting"],"answer":1,"rationale":"Parameter harus dikendalikan."},{"question":"Tool retak?","options":["Gunakan","Tahan, ganti, lapor","Pindah zona","Sembunyikan"],"answer":1,"rationale":"Tool rusak sumber kontaminasi."},{"question":"Dedicated scoop membantu…","options":["Mengurangi cross-contact","Mengganti cleaning","Menghapus label","Menentukan expiry"],"answer":0,"rationale":"Segregasi mengurangi perpindahan."},{"question":"Swab gagal tetapi visual bersih?","options":["Release","Hold, tindak lanjut, verify ulang","Hapus hasil","Ulang tanpa investigasi"],"answer":1,"rationale":"Evidence verification harus ditindaklanjuti."},{"question":"Konsentrasi chemical boleh diubah oleh…","options":["Siapa saja","Hanya melalui otorisasi/prosedur","Operator baru","Vendor transport"],"answer":1,"rationale":"Perubahan memerlukan authority."}],"assignment":["Demonstrasikan persiapan, tool selection, urutan cleaning, inspection, dan release flow.","Periksa label chemical simulasi dan jelaskan parameter yang tidak boleh ditebak.","Identifikasi dua pest risk serta dua allergen pathways.","Selesaikan capstone changeover."],"criticalBehavior":"Tidak release area setelah hasil gagal dan tidak memindahkan chemical ke wadah tanpa label.","rubric":[{"label":"Safety","weight":"25%"},{"label":"Urutan","weight":"25%"},{"label":"Contamination control","weight":"25%"},{"label":"Record & escalation","weight":"25%"}],"completion":["QFS-101 selesai.","Practical lab dan lesson selesai.","Post-test minimal 80.","OJT competent pada critical behavior."],"remedial":"Demonstrasi ulang pada langkah gagal, coaching Sanitation/Quality, dan set soal berbeda.","lessons":[{"intro":"Soil, protein, lemak, mineral, dan biofilm dapat melindungi mikroorganisme atau membawa alergen. Permukaan tampak bersih belum tentu memenuhi acceptance criteria.","points":["Desain alat, dead spot, gasket, drain, dan urutan pembongkaran memengaruhi hasil.","Cleaning menghilangkan soil; sanitation menurunkan mikroorganisme.","Ikuti urutan SSOP dan jangan menggabungkan tahap tanpa validasi.","Release hanya setelah inspection dan verification yang diwajibkan."],"scenario":"Susun urutan cleaning untuk equipment generik dan tandai titik dead spot.","checks":["Apa beda cleaning/sanitation?","Mengapa biofilm berisiko?","Siapa melepas area?"]},{"intro":"Chemical dan tools dikendalikan agar efektif tanpa menjadi sumber bahaya baru.","points":["Gunakan chemical approved sesuai identitas, konsentrasi, suhu, contact time, dan metode.","Periksa expiry, alat ukur, PPE, compatibility, storage, dan larangan pencampuran.","Pisahkan tools menurut zona dan simpan bersih/kering.","Tahan tool retak, aus, atau hilang bagian."],"scenario":"Pilih tool dan baca label chemical simulasi tanpa menggunakan bahan nyata.","checks":["Parameter apa yang tidak boleh ditebak?","Mengapa tool dipisahkan per zona?","Apa tindakan tool rusak?"]},{"intro":"Integrated pest management dimulai dari prevention, housekeeping, waste, door discipline, drain, incoming inspection, storage, dan exclusion.","points":["Kenali droppings, gnaw marks, webbing, insects, nesting, odor, damaged packaging, dan trap activity.","Jangan memindahkan device atau menyentuh bait.","Jangan menggunakan pestisida tanpa otorisasi.","Lindungi material dan jaga evidence saat eskalasi."],"scenario":"Tanda hama ditemukan dekat material. Tentukan hold, evidence, komunikasi, dan tindakan yang dilarang.","checks":["Apa prinsip prevention first?","Sebutkan lima tanda hama.","Apa yang tidak boleh dilakukan?"]},{"intro":"Alergen berpindah lewat shared equipment, dust, hands, tools, uniform, rework, storage, transfer, cleaning, atau wrong label.","points":["Gunakan segregation, covered transfer, scheduling, dedicated equipment, atau zoning sesuai risk assessment.","Validated cleaning dan line clearance penting saat changeover.","Rework restriction dan label reconciliation menjaga identitas.","Daftar alergen mengikuti produk serta ketentuan berlaku."],"scenario":"Petakan jalur cross-contact dari receiving hingga packaging.","checks":["Apa jalur cross-contact?","Mengapa scheduling membantu?","Apa peran label control?"]},{"intro":"Inspection menilai kebersihan visual/kondisi; verification menggunakan parameter, checklist, swab/test, record review, dan trend sesuai metode approved.","points":["Gunakan acceptance criteria resmi.","Hasil gagal mengalahkan asumsi visual bersih.","Jangan release; reclean atau tindakan lain sesuai prosedur.","Investigasi penyebab dan verifikasi ulang oleh pihak berwenang."],"scenario":"Visual bersih tetapi swab gagal. Susun response dan affected scope.","checks":["Apa beda inspection/verification?","Apa tindakan failed result?","Mengapa trend penting?"]},{"intro":"Capstone menyatukan sanitation, pest, allergen, dan label control dalam changeover.","points":["Tentukan stop dan affected scope.","Pisahkan cleaning response dari disposition produk.","Lakukan label reconciliation.","Jaga evidence dan eskalasi."],"scenario":"Setelah changeover ditemukan scoop salah zona, swab gagal, dan label lama tersisa.","checks":["Apa prioritas pertama?","Apa yang ditahan?","Siapa memberi release?"]}]},{"kind":"qfs","id":"QFS-205","title":"Non-Conformance, CAPA & RCA","shortTitle":"NC, CAPA & RCA","category":"QFS","level":"Intermediate","duration":"100 menit","summary":"Mengubah temuan dan deviasi menjadi containment, analisis akar penyebab, corrective action, serta verifikasi efektivitas yang kuat.","audience":"QA/QC, supervisor, process owner, warehouse, engineering, procurement, dan manager.","roles":["Produksi & Gudang","QA/QC","Procurement","PIC & Manager"],"credential":"Micro-credential Lahans · CAPA Practitioner","outcomes":["Mengklasifikasikan non-conformance dan menentukan containment.","Menggunakan 5 Why dan fishbone tanpa berhenti pada human error.","Menyusun CAPA SMART dan memverifikasi efektivitasnya."],"modules":[{"title":"NC & risk classification","lesson":"Sumber temuan, severity, scope, dan eskalasi","minutes":15},{"title":"Containment, correction & CA","lesson":"Perbedaan tindakan segera dan pencegahan berulang","minutes":15},{"title":"Problem statement","lesson":"Is/is not, bukti, dampak, dan batas masalah","minutes":14},{"title":"Root cause analysis","lesson":"5 Why, fishbone, data, dan uji hipotesis","minutes":20},{"title":"CAPA plan","lesson":"Owner, due date, resource, risiko perubahan, dan bukti","minutes":18},{"title":"Effectiveness & trending","lesson":"Indikator, periode observasi, closure, dan recurring issue","minutes":18}],"moduleCount":6,"prerequisite":"QFS-204","sources":[{"label":"FDA — Corrective and Preventive Actions","type":"Read more","url":"https://www.fda.gov/inspections-compliance-enforcement-and-criminal-investigations/inspection-guides/corrective-and-preventive-actions-capa"},{"label":"ASQ — Root Cause Analysis","type":"Toolkit","url":"https://asq.org/quality-resources/root-cause-analysis"},{"label":"Video: 5 Why root cause analysis","type":"YouTube","url":"https://www.youtube.com/results?search_query=5+why+root+cause+analysis+manufacturing"}],"quiz":[{"question":"Produk salah label baru ditemukan. Langkah awal adalah…","options":["Mencari siapa yang salah","Containment lot terdampak dan nilai risiko","Menutup temuan","Mengubah SOP saja"],"answer":1,"rationale":"Containment melindungi pelanggan dan mencegah perluasan dampak sebelum RCA selesai."},{"question":"Pernyataan 'operator kurang teliti' sebagai root cause biasanya…","options":["Sudah cukup","Perlu digali ke faktor sistem, metode, alat, atau kondisi","Tidak boleh dicatat","Selalu menjadi misconduct"],"answer":1,"rationale":"RCA harus menjelaskan mengapa sistem memungkinkan kesalahan terjadi dan berulang."},{"question":"CAPA dapat ditutup ketika…","options":["Tindakan selesai dikerjakan","Efektivitas diverifikasi dengan bukti","Form ditandatangani","Due date lewat"],"answer":1,"rationale":"Selesai mengerjakan tindakan belum membuktikan masalah tidak berulang."}],"pretest":[{"question":"Produk bocor dipindah ke hold. Ini…","options":["Containment","Root cause","Verification","Training"],"answer":0,"rationale":"Hold membatasi dampak."},{"question":"Ganti gasket otomatis tutup CAPA?","options":["Ya","Tidak","Ya bila lanjut","Ya bila tanpa complaint"],"answer":1,"rationale":"Perlu RCA/effectiveness."},{"question":"Problem statement baik?","options":["Fakta apa/di mana/kapan/berapa","Nama orang","Solusi saja","Asumsi"],"answer":0,"rationale":"Harus faktual."},{"question":"Operator tidak teliti adalah…","options":["Root cause final","Perlu diuji terhadap sistem","Corrective action","Effectiveness"],"answer":1,"rationale":"Jangan berhenti pada blame."},{"question":"CAPA efektif bila…","options":["Form ditutup","Kriteria outcome terpenuhi","Training selesai","Owner berganti"],"answer":1,"rationale":"Effectiveness berbasis hasil."}],"posttest":[{"question":"Correction adalah…","options":["Memperbaiki NC ditemukan","Bukti sistem efektif","Audit program","Critical limit"],"answer":0,"rationale":"Correction menangani kondisi ditemukan."},{"question":"Containment bertujuan…","options":["Membatasi dampak sementara","Menutup CAPA","Menetapkan root cause","Mengganti SOP"],"answer":0,"rationale":"Containment melindungi selama investigasi."},{"question":"Disposition harus…","options":["Diputus personel berwenang berbasis evidence","Operator","Selalu rework","Selalu scrap"],"answer":0,"rationale":"Disposition memerlukan authority."},{"question":"Root cause baik…","options":["Menjelaskan mekanisme dan evidence","Menyalahkan individu","Sama semua kasus","Tak perlu diuji"],"answer":0,"rationale":"RCA harus dapat diuji."},{"question":"Retraining sering tidak cukup karena…","options":["Tidak mengubah sistem","Terlalu murah","Tanpa owner","Tak bisa dicatat"],"answer":0,"rationale":"Recurrence sering bersifat sistemik."},{"question":"Effectiveness criterion…","options":["Ditentukan sebelum check","Setelah lihat hasil","Hanya tanggal","Selalu zero defect"],"answer":0,"rationale":"Pre-defined mencegah bias."},{"question":"Masalah serupa di line lain?","options":["Evaluasi common cause/horizontal deployment","Abaikan","Tutup CAPA","Hapus trend"],"answer":0,"rationale":"Learning harus sistemik."}],"assignment":["Review satu NC tertutup dengan data tersanitasi.","Periksa keterhubungan problem, containment, scope, RCA, action, dan effectiveness.","Identifikasi weak action dan usulkan kontrol lebih kuat.","Selesaikan case clinic complaint bocor."],"criticalBehavior":"Tidak mengubah disposition, due date, evidence, atau closure tanpa kewenangan; tidak memanipulasi data investigasi.","rubric":[{"label":"Problem & scope","weight":"20%"},{"label":"Evidence & RCA","weight":"30%"},{"label":"CAPA strength","weight":"25%"},{"label":"Effectiveness","weight":"15%"},{"label":"Communication","weight":"10%"}],"completion":["QFS-101 selesai; QFS-201 direkomendasikan.","Case clinic selesai minimal 80.","Post-test minimal 80.","Critical behavior lulus."],"remedial":"Coaching Quality, revisi case dan action plan, lalu reassessment dengan kasus berbeda.","lessons":[{"intro":"Non-conformance adalah ketidakpemenuhan requirement dari monitoring, inspection, audit, complaint, test, supplier, deviation, maintenance, atau observasi.","points":["Respons awal: stop, protect, report, record.","Tentukan affected scope sementara dan status material.","Containment membatasi dampak; correction memperbaiki kondisi ditemukan.","Disposition hanya oleh pihak berwenang."],"scenario":"Produk bocor ditemukan. Buat containment dan daftar evidence tanpa menyimpulkan root cause.","checks":["Apa beda containment/correction?","Siapa memberi disposition?","Apa yang dilindungi?"]},{"intro":"Problem statement yang baik menyebut requirement, kondisi aktual, lokasi, waktu, magnitude, lot, detection point, dan evidence.","points":["Hindari selalu, ceroboh, gagal total, atau aman tanpa data.","Scope mencakup period, batch, line, supplier, shift, customer, dan kondisi serupa.","Risk menentukan prioritas dan depth investigasi.","Pisahkan fakta, asumsi, dan unknown."],"scenario":"Ubah pernyataan 'operator ceroboh menyebabkan banyak produk rusak' menjadi problem statement faktual.","checks":["Apa unsur problem statement?","Bagaimana menentukan scope?","Mengapa risk assessment penting?"]},{"intro":"RCA dimulai dari evidence, bukan tool. Kumpulkan record, sample, interview, map, trend, alarm, maintenance, training, specification, change history, dan environment.","points":["5 Why cocok untuk jalur sebab relatif jelas.","Fishbone mengeksplorasi people, method, machine, material, measurement, environment, dan system.","Setiap dugaan harus diuji.","Root cause menjelaskan mengapa masalah terjadi dan kontrol gagal."],"scenario":"Bangun fishbone untuk kebocoran pasca pergantian supplier closure, lalu tandai evidence yang menguji tiap hipotesis.","checks":["Mengapa tool tidak menggantikan evidence?","Kapan gunakan 5 Why?","Apa ciri root cause actionable?"]},{"intro":"CAPA kuat mengendalikan penyebab melalui design, engineering, process, standard, poka-yoke, supplier control, atau monitoring.","points":["Training saja lemah bila sistem tetap memungkinkan error.","Pisahkan interim control dan permanent action.","Setiap action memiliki deliverable, owner, due date, dependency, evidence, change control, dan risk review.","Nilai unintended consequence sebelum implementasi."],"scenario":"Ubah action 'ingatkan operator' menjadi kontrol yang lebih kuat dan terukur.","checks":["Apa hirarki tindakan?","Apa isi action plan?","Apa beda interim/permanent action?"]},{"intro":"Completion membuktikan action dilakukan; effectiveness membuktikan outcome tercapai dengan indikator, sample, periode, dan tanpa dampak baru.","points":["Tentukan effectiveness criterion sebelum check.","Quality meninjau evidence, overdue, repeat issue, dan change impact.","Jangan tutup CAPA karena due date lewat.","Evaluasi horizontal deployment bila area lain memiliki common cause."],"scenario":"CAPA selesai dipasang tetapi defect muncul di line lain. Tentukan common-cause review dan effectiveness response.","checks":["Apa beda completion/effectiveness?","Kapan CAPA ditutup?","Apa itu horizontal deployment?"]},{"intro":"Case clinic mengintegrasikan problem definition, scope, evidence, RCA, CAPA, dan effectiveness.","points":["Jaga data integrity selama investigasi.","Hubungkan setiap action dengan root cause.","Tentukan owner dan authority.","Komunikasikan risk serta status produk secara konsisten."],"scenario":"Complaint bocor naik pada dua SKU setelah pergantian supplier closure.","checks":["Apa affected scope?","Evidence apa yang dikumpulkan?","Apa effectiveness criterion?"]}]},{"kind":"sample","id":"REG-201","title":"Claims, BPOM & Halal by Design","shortTitle":"Claims, BPOM & Halal by Design","category":"Product & Innovation","level":"Intermediate","duration":"105 menit","summary":"Menanamkan persyaratan BPOM, halal, label, alergen, klaim, dan bukti sejak awal pengembangan produk.","audience":"Regulatory, R&D, QA, marketing, packaging, dan commercial approver","roles":["QA/QC","Sales & Marketing","R&D & Engineering"],"credential":"Regulatory-by-Design badge","assessment":"Artwork and claim approval case","modules":[{"title":"Regulatory pathway"},{"title":"Halal and material evidence"},{"title":"Label & allergen"},{"title":"Claims substantiation"}],"moduleCount":4,"prerequisite":"RND-101","sources":[],"quiz":[]},{"kind":"sample","id":"SAL-201","title":"Commercial Negotiation","shortTitle":"Commercial Negotiation","category":"Sales & Marketing","level":"Intermediate","duration":"110 menit","summary":"Menegosiasikan harga, volume, promosi, term, dan service level dengan persiapan BATNA serta guardrail margin.","audience":"Sales executive, key account, procurement interface, dan sales manager","roles":["PIC & Manager","Procurement","Sales & Marketing"],"credential":"Commercial Negotiator badge","assessment":"Commercial negotiation simulation","modules":[{"title":"Negotiation brief"},{"title":"BATNA & guardrails"},{"title":"Trade variables"},{"title":"Closing & documentation"}],"moduleCount":4,"prerequisite":"SAL-101","sources":[],"quiz":[]},{"kind":"sample","id":"SCM-201","title":"3PL, Expedition & Transport Claims","shortTitle":"3PL, Expedition & Transport Claims","category":"Supply Chain","level":"Intermediate","duration":"100 menit","summary":"Memilih moda dan ekspedisi, mengelola 3PL SLA, menjaga transport integrity, serta menutup claim dengan bukti yang cukup.","audience":"Logistics, warehouse, procurement, customer service, dan distribution PIC","roles":["Procurement","Produksi & Gudang","Sales & Marketing"],"credential":"Logistics Practitioner badge","assessment":"Shipment exception case","modules":[{"title":"First, middle & last mile"},{"title":"Mode and expedition selection"},{"title":"3PL SLA & control tower"},{"title":"Damage, POD & claim"}],"moduleCount":4,"prerequisite":"SCM-101","sources":[],"quiz":[]},{"kind":"sample","id":"FWB-401","title":"Personal Financial Wellbeing Plan","shortTitle":"Personal Financial Wellbeing Plan","category":"Financial Wellbeing","level":"Advanced","duration":"80 menit","summary":"Menggabungkan arus kas, dana darurat, utang, proteksi, dan tujuan menjadi rencana 12 bulan yang terukur.","audience":"Seluruh karyawan","roles":["Seluruh karyawan"],"credential":"Lahans Financial Wellbeing Certificate","assessment":"Capstone 12-month financial plan","modules":[{"title":"Financial health score"},{"title":"Risk protection"},{"title":"12-month roadmap"},{"title":"Habit system"},{"title":"Quarterly review"}],"moduleCount":5,"prerequisite":"FWB-201","sources":[],"quiz":[]},{"kind":"sample","id":"LDR-401","title":"Negotiation & Decision Making","shortTitle":"Negotiation & Decision Making","category":"Leadership","level":"Advanced","duration":"125 menit","summary":"Mempersiapkan negosiasi, mengelola kepentingan, mengevaluasi trade-off, dan mengambil keputusan berkualitas.","audience":"Manager dan functional lead","roles":["PIC & Manager"],"credential":"Leadership Practitioner badge","assessment":"Negotiation simulation + decision memo","modules":[{"title":"Interests vs positions"},{"title":"BATNA & concessions"},{"title":"Decision criteria"},{"title":"Bias & risk"},{"title":"Negotiation simulation"}],"moduleCount":5,"prerequisite":"LDR-301","sources":[],"quiz":[]},{"kind":"sample","id":"LDR-501","title":"Leading High-Performing Teams","shortTitle":"Leading High-Performing Teams","category":"Leadership","level":"Advanced","duration":"140 menit","summary":"Merancang ritme tim, delegasi, coaching, talent review, dan perbaikan kinerja yang berkelanjutan.","audience":"Senior manager dan head","roles":["PIC & Manager"],"credential":"Lahans Leadership Certificate","assessment":"Capstone 90-day team plan","modules":[{"title":"Team operating model"},{"title":"Delegation & empowerment"},{"title":"Performance rhythm"},{"title":"Talent & succession"},{"title":"90-day team plan"}],"moduleCount":5,"prerequisite":"LDR-401","sources":[],"quiz":[]},{"kind":"qfs","id":"QFS-301","title":"Internal Audit for PIC","shortTitle":"Internal Audit","category":"QFS","level":"Advanced","duration":"150 menit","summary":"Praktik audit internal berbasis risiko: program audit, checklist, sampling, interview, bukti objektif, penulisan temuan, dan follow-up CAPA.","audience":"Calon auditor internal, QA/QC, PIC sistem, process owner, dan manager.","roles":["QA/QC","PIC & Manager"],"credential":"Sertifikat Lahans · Internal Auditor (teori + simulasi)","outcomes":["Merencanakan audit berbasis risiko dan memilih sampel yang relevan.","Melakukan interview serta menguji bukti dengan objektif.","Menulis temuan yang jelas dan memverifikasi CAPA."],"modules":[{"title":"Prinsip & etika audit","lesson":"Integritas, objektivitas, confidentiality, dan evidence-based approach","minutes":20},{"title":"Program & audit plan","lesson":"Scope, criteria, tim, jadwal, dan prioritas risiko","minutes":20},{"title":"Checklist & sampling","lesson":"Process approach, trail, record sampling, dan risk focus","minutes":22},{"title":"Opening, interview & observation","lesson":"Pertanyaan terbuka, triangulasi, dan catatan audit","minutes":25},{"title":"Menulis temuan","lesson":"Requirement, evidence, gap, klasifikasi, dan dampak","minutes":23},{"title":"Closing & report","lesson":"Alignment fakta, no surprise, dan laporan ringkas","minutes":18},{"title":"CAPA follow-up","lesson":"Review RCA, bukti implementasi, dan effectiveness check","minutes":22}],"moduleCount":7,"prerequisite":"QFS-205","sources":[{"label":"ISO 19011 — Auditing management systems","type":"Standar","url":"https://www.iso.org/standard/70017.html"},{"label":"ASQ — Auditing resources","type":"Read more","url":"https://asq.org/quality-resources/auditing"},{"label":"Video: internal audit techniques","type":"YouTube","url":"https://www.youtube.com/results?search_query=internal+audit+techniques+food+safety"}],"quiz":[{"question":"Temuan audit yang kuat memuat…","options":["Opini auditor","Requirement, bukti objektif, dan gap","Nama orang yang salah","Solusi wajib dari auditor"],"answer":1,"rationale":"Temuan harus dapat ditelusuri ke kriteria audit dan bukti yang dapat diverifikasi."},{"question":"Saat jawaban interview berbeda dari catatan, auditor sebaiknya…","options":["Memilih jawaban senior","Melakukan triangulasi bukti","Langsung tulis major","Menghentikan audit"],"answer":1,"rationale":"Auditor membandingkan interview, observasi, dan rekaman sebelum menarik kesimpulan."},{"question":"Auditor internal sebaiknya…","options":["Mengaudit pekerjaannya sendiri","Independen dari aktivitas yang diaudit sejauh praktis","Menentukan seluruh solusi","Mengabaikan risiko rendah"],"answer":1,"rationale":"Independensi mendukung objektivitas dan kredibilitas hasil audit."}],"pretest":[{"question":"Tujuan internal audit?","options":["Mencari salah","Menilai conformity/effectiveness berbasis evidence","Menutup CAPA","Mengganti inspeksi"],"answer":1,"rationale":"Audit menilai secara objektif."},{"question":"Satu opini cukup?","options":["Ya","Tidak","Ya bila senior","Ya bila auditee setuju"],"answer":1,"rationale":"Kesimpulan memerlukan evidence memadai."},{"question":"Scope menetapkan…","options":["Batas proses/lokasi/periode","Jawaban finding","Nama orang","Tindakan"],"answer":0,"rationale":"Scope menetapkan batas audit."},{"question":"Finding baik?","options":["Criteria, evidence, gap","Opini","Solusi wajib","Kata umum"],"answer":0,"rationale":"Finding harus tertelusur."},{"question":"Risiko langsung ditemukan?","options":["Tunggu closing","Immediate escalation","Sembunyikan","Ubah scope diam-diam"],"answer":1,"rationale":"Risk kritis tidak menunggu report."}],"posttest":[{"question":"Evidence-based berarti…","options":["Kesimpulan didukung informasi terverifikasi","Auditor selalu benar","Semua record diperiksa","Interview dilarang"],"answer":0,"rationale":"Kesimpulan tertelusur ke evidence."},{"question":"Risk-based approach memengaruhi…","options":["Prioritas, depth, sampling, resource","Warna checklist","Nama auditee","Sertifikat"],"answer":0,"rationale":"Risiko mengarahkan audit."},{"question":"Audit criteria adalah…","options":["Requirement pembanding evidence","Opini","Action plan","Hasil"],"answer":0,"rationale":"Criteria adalah basis evaluasi."},{"question":"Triangulation…","options":["Membandingkan beberapa evidence","Bertanya tiga kali","Tiga auditor","Tiga finding"],"answer":0,"rationale":"Kombinasi evidence meningkatkan reliability."},{"question":"Sampling limitation…","options":["Dipahami dan dicatat bila material","Disembunyikan","Dianggap tak ada","Diganti asumsi"],"answer":0,"rationale":"Sampling memiliki batas."},{"question":"Audit pekerjaan sendiri?","options":["Ungkap conflict dan ikuti keputusan program owner","Tetap tanpa catatan","Hapus area","Nilai ringan"],"answer":0,"rationale":"Independence harus dikelola."},{"question":"Course completion otomatis qualified?","options":["Tidak; perlu witnessed performance dan approval","Ya","Ya tanpa scope","Hanya bila 100"],"answer":0,"rationale":"Qualification memerlukan demonstrasi kompetensi."}],"assignment":["Susun objective, scope, criteria, agenda, dan sampling plan.","Lakukan opening, interview, observation, record review, dan triangulation pada simulation pack.","Tulis finding yang menghubungkan criteria–evidence–gap.","Lakukan closing dan report.","Selesaikan satu witnessed audit untuk scope yang ditetapkan."],"criticalBehavior":"Jujur terhadap evidence, menjaga confidentiality, mengungkap conflict, tidak mengaudit dengan bias tersembunyi, dan segera mengeskalasi risiko kritis.","rubric":[{"label":"Planning","weight":"20%"},{"label":"Opening & communication","weight":"10%"},{"label":"Evidence & triangulation","weight":"25%"},{"label":"Notes & traceability","weight":"15%"},{"label":"Finding","weight":"20%"},{"label":"Closing & confidentiality","weight":"10%"}],"completion":["QFS-101 dan minimal dua course scope selesai.","Post-test minimal 80.","Simulation minimal 80.","Witnessed audit competent untuk status Qualified."],"remedial":"Coaching, revisi plan/report, simulation ulang, dan witnessed reassessment sesuai gap.","lessons":[{"intro":"Audit adalah proses sistematis untuk mengumpulkan dan mengevaluasi evidence secara objektif terhadap criteria.","points":["Audit berbeda dari inspection, investigation, surveillance, atau konsultasi.","Prinsip: integrity, fair presentation, due care, confidentiality, independence, evidence-based, dan risk-based.","Kelola conflict of interest dan tekanan.","Jaga informasi sensitif sesuai scope."],"scenario":"Bedakan audit, inspeksi harian, dan investigasi complaint pada tiga contoh.","checks":["Apa tujuan audit?","Apa arti independence?","Bagaimana mengelola conflict?"]},{"intro":"Program audit berbasis risiko mengatur frekuensi dan prioritas berdasarkan criticality, perubahan, performance, complaint, incident, CAPA, serta audit sebelumnya.","points":["Audit plan memuat objective, scope, criteria, team, agenda, owner, lokasi, waktu, metode, dan dokumen awal.","Sampling plan disusun sebelum audit.","Plan dapat disesuaikan berdasarkan evidence dengan komunikasi.","Resource dialokasikan ke risiko tertinggi."],"scenario":"Susun plan audit receiving–storage–label control.","checks":["Apa isi scope?","Apa pemicu frekuensi audit?","Apa isi sampling plan?"]},{"intro":"Criteria berasal dari SOP, standard, regulation, specification, contract, HACCP/SJPH plan, atau policy yang berlaku.","points":["Gunakan process approach: input–process–output–control–record–performance.","Checklist adalah aide-memoire, bukan batas pertanyaan.","Siapkan open question dan follow-up.","Petakan sample ke objective dan risiko."],"scenario":"Ubah checklist clause-only menjadi process trail untuk receiving.","checks":["Apa itu audit criteria?","Apa kekurangan checklist kaku?","Apa itu process trail?"]},{"intro":"Pelaksanaan audit dimulai dengan opening, lalu interview, observation, document review, dan record sampling.","points":["Opening mengonfirmasi objective, scope, criteria, agenda, safety, confidentiality, dan escalation.","Triangulate: bandingkan yang dikatakan, ditulis, dilakukan, dan dicatat.","Catat sample, lot, period, area, dan alasan perluasan.","Jangan berdebat atau mengarahkan jawaban."],"scenario":"Jawaban interview berbeda dari record dan observasi. Rancang triangulation berikutnya.","checks":["Apa isi opening?","Apa itu triangulation?","Apa limitation sampling?"]},{"intro":"Finding menghubungkan criteria, objective evidence, dan gap secara jelas tanpa dugaan akar sebab atau solusi preskriptif.","points":["Hindari nama orang, emosi, rumor, dan generalisasi.","Klasifikasi mengikuti prosedur Lahans.","Disagreement dicatat dan diselesaikan melalui jalur resmi.","Immediate risk dieskalasi segera tanpa mengambil disposition di luar authority."],"scenario":"Tulis finding dari requirement label check dan tiga record yang tidak memiliki verifikasi.","checks":["Apa tiga unsur finding?","Siapa mengklasifikasi?","Apa tindakan immediate risk?"]},{"intro":"Closing menyampaikan coverage, strength bila relevan, finding, limitation, next steps, owner, dan timeline. Report harus akurat, ringkas, dan tertelusur.","points":["Tidak ada surprise: fakta material dibahas selama audit.","Auditee memiliki corrective action.","Auditor menilai evidence tanpa mengambil ownership action.","Confidentiality dijaga dalam distribusi report."],"scenario":"Lakukan closing singkat untuk dua finding dan satu limitation sampling.","checks":["Apa isi closing?","Siapa memiliki action?","Bagaimana menjaga confidentiality?"]},{"intro":"Status Trained diperoleh setelah course; Qualified memerlukan witnessed performance, scope, feedback, dan approval Quality.","points":["Follow-up menilai completion dan effectiveness sesuai peran.","Closure tidak hanya berdasarkan jawaban tertulis.","Kompetensi dipelihara melalui audit log, calibration, feedback, dan refresher.","Auditor tidak mengaudit pekerjaannya sendiri bila objektivitas terdampak."],"scenario":"Lakukan witnessed audit receiving–storage–label dengan SOP, records, kondisi, dan transcript.","checks":["Apa beda Trained/Qualified?","Apa evidence competence?","Kapan reassessment diperlukan?"]}]}],"paths":[{"id":"qfs","title":"Quality & Food Safety Academy","eyebrow":"Mandatory + role-based","description":"Fondasi keamanan pangan hingga kompetensi assurance dan internal audit.","audience":"Operasional, QA/QC, procurement, PIC & manager","duration":"12–16 jam","courseIds":["QFS-101","QFS-201","QFS-202","QFS-203","QFS-204","QFS-205","QFS-301"],"tone":"blue","letter":"Q"},{"id":"onboarding","title":"New Hire Onboarding","eyebrow":"First 30 days","description":"Jalur terarah dari orientasi perusahaan sampai validasi kesiapan menjalankan peran.","audience":"Seluruh karyawan baru","duration":"4–5 jam + OJT","courseIds":["ONB-101","ONB-102","ONB-103","ONB-104","ONB-105"],"tone":"teal","letter":"O"},{"id":"leadership","title":"Leadership Accelerator","eyebrow":"Aspiring leader to head","description":"Kurikulum kepemimpinan berjenjang dari self-leadership hingga membangun tim berkinerja tinggi.","audience":"Talent pool, supervisor, manager & head","duration":"9–12 jam + praktik","courseIds":["LDR-101","LDR-201","LDR-301","LDR-401","LDR-501"],"tone":"violet","letter":"L"},{"id":"professional","title":"Communication Mastery","eyebrow":"Cross-functional skills","description":"Komunikasi, public speaking, negosiasi, dan difficult conversation untuk pekerjaan sehari-hari.","audience":"Seluruh karyawan dan people manager","duration":"6–8 jam + simulasi","courseIds":["COM-101","COM-201","NEG-201","DFC-201"],"tone":"orange","letter":"C"},{"id":"financial","title":"Financial Wellbeing","eyebrow":"Employee wellbeing","description":"Membangun fondasi finansial, menghindari pinjol dan judol, lalu menyusun rencana keuangan pribadi.","audience":"Seluruh karyawan","duration":"5–7 jam","courseIds":["FWB-101","FWB-102","FWB-201","FWB-301","FWB-401"],"tone":"navy","letter":"F"},{"id":"digital","title":"Data, AI & Digital Productivity","eyebrow":"Role-based foundation","description":"Google Workspace, data literacy, security, dan penggunaan AI yang bertanggung jawab untuk produktivitas kerja.","audience":"Seluruh karyawan, analyst, dan manager","duration":"5–8 jam + praktik","courseIds":["GWS-101","GWS-102","GWS-103","ONB-104"],"tone":"blue","letter":"D"},{"id":"commercial","title":"Commercial Excellence","eyebrow":"Sales & customer growth","description":"Product knowledge, consultative selling, commercial negotiation, dan business acumen untuk pertumbuhan yang sehat.","audience":"Sales, marketing, key account, dan commercial leader","duration":"6–9 jam + field coaching","courseIds":["SAL-101","SAL-201","NEG-201","BIZ-101"],"tone":"orange","letter":"S"},{"id":"supply","title":"Packaging & Logistics Specialist","eyebrow":"Operations specialist","description":"Alur supply chain, material packaging, ekspedisi, 3PL, transport integrity, POD, dan claim.","audience":"Supply chain, warehouse, procurement, packaging, dan QA","duration":"7–10 jam + OJT","courseIds":["SCM-101","SCM-201","QFS-203","QFS-204"],"tone":"green","letter":"P"},{"id":"innovation","title":"Product Innovation & Commercialization","eyebrow":"Cross-functional stage-gate","description":"Dari product brief sampai gate review, scale-up, regulatory readiness, dan launch evidence.","audience":"R&D, marketing, QA, regulatory, packaging, operations, dan procurement","duration":"8–12 jam + capstone","courseIds":["RND-101","REG-201","QFS-203","PM-101"],"tone":"slate","letter":"I"},{"id":"opex","title":"Project & Operational Excellence","eyebrow":"Improvement capability","description":"Business acumen, project delivery, structured problem solving, dan penerapan perbaikan terukur.","audience":"Process owner, supervisor, project lead, dan manager","duration":"7–9 jam + project","courseIds":["BIZ-101","PM-101","OPEX-101","LDR-201"],"tone":"violet","letter":"X"}],"knowledge":[{"code":"PRD","title":"Product Portfolio","description":"Kategori, SKU, key attributes, handling, use case, dan FAQ.","tabId":"t.0","tone":"blue"},{"code":"BRD","title":"Brand Portfolio","description":"Positioning, audience, brand voice, approved claims, dan asset reference.","tabId":"t.65lj1qn9pjl8","tone":"violet"},{"code":"CMP","title":"Competitor Intelligence","description":"Perbandingan faktual nasional, regional, dan lokal dengan guardrail etika.","tabId":"t.3mbqpvd9xq8a","tone":"orange"},{"code":"PKG","title":"Packaging Material Library","description":"Specification, defect library, compatibility, inspection, handling, dan storage.","tabId":"t.pvnyevtu0t7b","tone":"teal"},{"code":"OEM","title":"OEM & Co-Manufacturing","description":"Qualification, technical agreement, audit evidence, release, change, dan escalation.","tabId":"t.8g5gac7aikia","tone":"navy"},{"code":"REG","title":"Certifications & Regulatory","description":"Halal, BPOM, HACCP, ISO/FSSC, BRCGS, Organic, dan GS1 reference.","tabId":"t.djgi4nvap0n","tone":"green"}],"categories":["Semua kategori","Digital Productivity","Engineering & Reliability","Finance & Business","Financial Wellbeing","Leadership","Legal & Compliance","Onboarding","Product & Innovation","Professional Skills","Project & Operational Excellence","QFS","Sales & Marketing","Supply Chain"],"roles":["Semua peran","Seluruh karyawan","Produksi & Gudang","QA/QC","Procurement","Sales & Marketing","Finance & HR","R&D & Engineering","PIC & Manager"],"levels":["Semua level","Foundation","Intermediate","Advanced"],"qfs101Modules":[{"objectives":["Menjelaskan mengapa keamanan pangan merupakan tanggung jawab setiap fungsi.","Membedakan laporan fakta, asumsi, near miss, dan deviasi aktual.","Menggunakan jalur Stop–Protect–Report–Record saat menemukan risiko.","Menunjukkan perilaku speak-up tanpa menunggu audit atau instruksi Quality."],"sections":[{"title":"Budaya keamanan pangan adalah cara mengambil keputusan","paragraphs":["Budaya keamanan pangan bukan poster, slogan, atau kegiatan menjelang audit. Budaya terlihat dari keputusan sehari-hari ketika target produksi, biaya, waktu, dan keselamatan konsumen saling bertentangan. Organisasi dengan budaya kuat memilih tindakan yang melindungi konsumen, menjaga bukti, dan melibatkan pihak berwenang sebelum proses dilanjutkan.","Setiap orang memiliki tanggung jawab sesuai perannya. Operator menjalankan kontrol dan melaporkan abnormalitas; gudang menjaga identitas, status, dan kondisi material; Engineering memastikan intervensi tidak mencemari produk; Procurement mengendalikan pemasok dan perubahan; supervisor menyediakan waktu serta sumber daya; Quality menilai bukti dan memberi keputusan sesuai kewenangan. Tanggung jawab bersama bukan berarti semua orang boleh memberikan release atau disposition."],"bullets":["Food safety didahulukan ketika terdapat risiko yang masuk akal terhadap konsumen.","Authority harus jelas: siapa menghentikan, menahan, menilai, dan melepas produk.","Pelaporan jujur harus dilindungi; menyembunyikan masalah memperbesar affected scope."]},{"title":"Near miss, deviasi, dan eskalasi faktual","paragraphs":["Near miss adalah kejadian yang belum menimbulkan produk tidak aman tetapi menunjukkan kontrol dapat gagal—misalnya baut hampir jatuh, pintu zona terbuka, label lama hampir digunakan, atau alarm muncul lalu hilang. Deviasi adalah ketidaksesuaian terhadap persyaratan, prosedur, atau kondisi yang ditetapkan. Keduanya perlu dicatat karena near miss hari ini dapat menjadi insiden besok.","Laporan yang baik menjawab apa yang terlihat, lokasi, waktu, produk atau lot terkait, kondisi proses, tindakan perlindungan awal, dan bukti yang tersedia. Hindari menyimpulkan akar masalah tanpa investigasi. Kalimat ‘alarm metal detector muncul tiga kali pada pukul 14.10–14.17, produk setelah pemeriksaan valid terakhir dipisahkan’ lebih berguna daripada ‘mesinnya rusak lagi’."]},{"title":"Peran pimpinan dan psychological safety","paragraphs":["Pimpinan membentuk budaya melalui apa yang diukur, ditanyakan, diberikan sumber daya, dan ditoleransi. Jika orang yang menghentikan proses selalu disalahkan, risiko akan disembunyikan. Sebaliknya, pemimpin yang berterima kasih atas laporan, memeriksa fakta, dan menutup feedback loop membuat karyawan lebih cepat speak-up.","Speak-up bukan izin untuk menyebarkan rumor atau melewati jalur komunikasi. Peserta tetap harus melindungi produk, menjaga kerahasiaan, menggunakan bahasa faktual, dan menaikkan eskalasi bila risiko kritis tidak ditanggapi."]}],"playbook":["STOP aktivitas yang dapat memperbesar risiko apabila aman dilakukan.","PROTECT produk, material, area, dan bukti; gunakan status hold sesuai prosedur.","REPORT fakta kepada PIC/supervisor/Quality melalui jalur resmi.","RECORD waktu, lot, kondisi, tindakan awal, dan pihak yang telah dihubungi.","FOLLOW UP sampai ada respons berwenang; naikkan eskalasi untuk risiko kritis yang belum tertangani."],"redFlags":["Alarm atau interlock berulang","Tekanan untuk melewati pemeriksaan","Catatan diminta diisi dari ingatan","Produk dipindah tanpa status","Near miss yang sama berulang"],"mistakes":[{"title":"Menunggu Quality melihat sendiri","explanation":"Risiko dapat meluas. Orang yang menemukan kondisi harus segera melindungi dan melaporkan sesuai perannya."},{"title":"Menghentikan proses tanpa menjaga bukti","explanation":"Stop penting, tetapi produk, waktu, lot, alarm, sample, dan record juga harus diamankan untuk penilaian."},{"title":"Menganggap target sebagai alasan bypass","explanation":"Target tidak mengubah persyaratan food safety atau kewenangan release."}],"cases":[{"title":"Alarm menjelang akhir shift","level":"Rutin","situation":"Metal detector memberi alarm tiga kali dalam tujuh menit. Supervisor mengatakan target tinggal sedikit dan meminta produk terus berjalan sambil menunggu Engineering.","facts":["Alarm terjadi pada lini aktif.","Waktu pemeriksaan valid terakhir tersedia.","Penyebab alarm belum diketahui.","Sebagian produk telah melewati titik pemeriksaan."],"prompts":["Apa tindakan pertama?","Produk mana yang menjadi affected window sementara?","Informasi apa yang dicatat?","Siapa yang harus dilibatkan?"],"response":["Hentikan aliran sesuai prosedur dan jangan bypass alarm.","Tahan produk sejak pemeriksaan valid terakhir sampai titik kendali dipulihkan.","Catat waktu, frekuensi alarm, lot, setting/status alat, dan tindakan awal.","Libatkan supervisor, Quality, dan Engineering; release hanya oleh pihak berwenang berbasis bukti."],"lesson":"Alarm adalah informasi kontrol. Reset tidak menghapus risiko atau affected scope."},{"title":"Record diminta disamakan","level":"Kritis","situation":"Hasil pemeriksaan suhu pada dua jam terakhir kosong. Rekan senior meminta peserta menyalin angka jam sebelumnya agar batch tidak tertahan.","facts":["Observasi aktual tidak dilakukan atau tidak tercatat.","Produk sudah diproses.","Angka yang diminta tidak mewakili pengukuran aktual.","Ada tekanan dari rekan yang lebih senior."],"prompts":["Apa risiko terhadap konsumen dan data integrity?","Apa yang tidak boleh dilakukan?","Bagaimana mengeskalasi tanpa menuduh?"],"response":["Jangan mengarang, menyalin, atau backdate hasil.","Lindungi record asli dan identifikasi periode data yang hilang.","Laporkan fakta dan tahan produk bila diwajibkan oleh prosedur/risk assessment.","Quality/pihak berwenang menentukan bukti tambahan dan disposition."],"lesson":"Catatan palsu menghilangkan kemampuan organisasi membuktikan kontrol dan mengambil keputusan aman."}],"summary":["Food safety adalah tanggung jawab lintas fungsi, tetapi release tetap berbasis kewenangan.","Near miss dilaporkan sebelum berubah menjadi insiden.","Gunakan Stop–Protect–Report–Record.","Laporkan fakta, bukan kesimpulan akar sebab.","Target tidak pernah membenarkan bypass kontrol atau pemalsuan record.","Pimpinan wajib melindungi speak-up dan menutup feedback loop."],"knowledgeCheck":[{"question":"Alarm kontrol berulang, tetapi produk terlihat normal. Tindakan terbaik?","options":["Lanjut sampai ada defect visual","Reset lalu lanjut","Stop sesuai prosedur, tahan affected window, dan eskalasi","Catat saat shift selesai"],"answer":2,"rationale":"Kondisi visual tidak menggantikan kontrol. Produk terkait perlu dilindungi sampai penilaian berwenang."},{"question":"Laporan eskalasi yang paling faktual adalah…","options":["Mesin selalu bermasalah","Operator sebelumnya ceroboh","Alarm terjadi 3 kali pukul 14.10–14.17 pada lot X; produk sejak check terakhir dipisahkan","Pasti ada logam di produk"],"answer":2,"rationale":"Laporan yang baik menyebut waktu, lot, observasi, dan tindakan awal tanpa menebak akar sebab."},{"question":"Near miss perlu dicatat karena…","options":["Hanya untuk audit","Menunjukkan kontrol dapat gagal sebelum konsumen terdampak","Selalu berarti recall","Menggantikan corrective action"],"answer":1,"rationale":"Near miss memberi kesempatan melakukan perbaikan sebelum terjadi insiden aktual."},{"question":"Siapa yang boleh memberikan release produk hold?","options":["Siapa yang menemukan","Personel berwenang sesuai prosedur berbasis bukti","Operator paling senior","Vendor"],"answer":1,"rationale":"Tanggung jawab bersama tidak menghapus batas kewenangan disposition dan release."}],"sources":[{"label":"General Principles of Food Hygiene (CXC 1-1969)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/publications/en/"},{"label":"PerBPOM 22/2021 — Izin Penerapan CPPOB","organization":"BPOM RI","url":"https://jdih.pom.go.id/view/slide/1304/22/2021/06a0fe35df30cece15afd1c19acc5c3f"}]},{"objectives":["Mengklasifikasikan bahaya biologis, kimia, fisik, dan alergen.","Membedakan hazard, sumber, jalur kontaminasi, dan control measure.","Menilai affected scope awal tanpa membuat disposition.","Memilih tindakan perlindungan awal untuk tiap kelompok bahaya."],"sections":[{"title":"Bahaya bukan sekadar benda yang terlihat","paragraphs":["Hazard adalah agen biologis, kimia, fisik, atau alergen yang berpotensi menyebabkan dampak kesehatan. Risk mempertimbangkan kemungkinan dan keparahan dalam konteks produk, proses, konsumen, serta kontrol yang tersedia. Kondisi kotor, suhu tidak terkendali, atau tutup chemical terbuka bukan selalu hazard itu sendiri, tetapi dapat menjadi sumber atau jalur masuk hazard.","Satu kejadian dapat melibatkan lebih dari satu bahaya. Kebocoran dari area maintenance dapat membawa pelumas (kimia), serpihan logam (fisik), dan air yang mendukung pertumbuhan mikroba (biologis). Karena itu respons tidak boleh berhenti setelah satu bahaya ditemukan."],"bullets":["Biologis: bakteri, virus, parasit, kapang tertentu, dan toksin biologis.","Kimia: residu cleaning, pelumas, pestisida, dosis BTP salah, migrasi, atau kontaminan.","Fisik: kaca, logam, batu, kayu, plastik keras, tulang, atau bagian alat.","Alergen: protein alergen yang disengaja atau hadir tidak sengaja melalui cross-contact/mislabeling."]},{"title":"Dari sumber menuju konsumen","paragraphs":["Analisis sederhana mengikuti rantai sumber–jalur–produk–konsumen. Tanyakan: dari mana bahaya berasal, bagaimana berpindah, produk/lot mana yang mungkin terpapar, kontrol mana yang seharusnya mencegah atau mendeteksi, dan bukti apa yang menunjukkan kontrol bekerja.","Tidak semua bahaya dapat dideteksi secara visual. Mikroorganisme, residu chemical, dan protein alergen dapat tidak terlihat atau tidak berbau. Karena itu keputusan harus menggunakan spesifikasi, record, hasil monitoring, inspeksi, pengujian, dan penilaian berwenang."]},{"title":"Control measure dan batas peran","paragraphs":["Control measure dapat berupa approved supplier, treatment proses, segregasi, sanitation, saringan, magnet, detector, label verification, temperature control, atau kombinasi beberapa kontrol. Peserta foundation perlu mengenali kontrol dan deviasi, tetapi tidak menetapkan sendiri critical limit, spesifikasi, atau disposition.","Saat status belum jelas, tindakan aman adalah menghentikan perluasan risiko, menahan produk/material terkait, menjaga bukti, dan mengeskalasi. ‘Belum tahu’ adalah informasi yang harus dikelola, bukan alasan menganggap aman."]}],"playbook":["IDENTIFY kemungkinan kelompok bahaya.","LOCATE sumber dan jalur perpindahan.","BOUND affected scope sementara berdasarkan waktu, lot, area, alat, dan aliran material.","CONTROL perluasan risiko: stop, cover, segregate, hold, atau batasi akses sesuai prosedur.","ESCALATE dengan bukti; jangan memberikan release di luar kewenangan."],"redFlags":["Material tanpa identitas","Benda rapuh pecah","Suhu di luar ketentuan","Chemical tanpa label","Perubahan warna/bau yang tidak biasa","Alat hilang bagian","Alergen tidak sesuai label"],"mistakes":[{"title":"Menganggap bahaya hanya benda asing","explanation":"Bahaya mikrobiologis, kimia, dan alergen sering tidak terlihat."},{"title":"Mencium atau mencicipi untuk memastikan","explanation":"Cara ini tidak membuktikan keamanan dan dapat membahayakan pekerja."},{"title":"Membuang bukti sebelum dicatat","explanation":"Bukti diperlukan untuk menentukan scope, penyebab, dan tindakan selanjutnya."}],"cases":[{"title":"Empat temuan pada satu inspeksi","level":"Rutin","situation":"Saat inspeksi ditemukan baut longgar, botol spray tanpa label, tepung mengandung alergen tanpa identitas, dan bahan dingin berada di area ambient.","facts":["Empat temuan terjadi di area berbeda.","Status paparan produk belum diketahui.","Ada potensi fisik, kimia, alergen, dan biologis."],"prompts":["Klasifikasikan setiap bahaya.","Apa containment awalnya?","Bukti apa yang dikumpulkan?"],"response":["Amankan tiap area dan cegah penggunaan material terkait.","Tahan affected scope sementara berdasarkan jalur paparan.","Jaga baut/botol/material dan catat lot, waktu, lokasi, serta kondisi suhu.","Eskalasi ke pemilik proses dan Quality untuk penilaian."],"lesson":"Klasifikasi membantu memilih kontrol, tetapi satu kejadian dapat memerlukan beberapa containment."},{"title":"Kaca pecah di dekat open product","level":"Kritis","situation":"Lampu berpelindung retak dan pecahan ditemukan dua meter dari produk terbuka. Seorang pekerja mulai menyapu sebelum area difoto atau dibatasi.","facts":["Produk terbuka berada di area.","Arah sebaran pecahan belum dipetakan.","Cleaning dimulai sebelum evidence diamankan."],"prompts":["Apa tindakan segera?","Bagaimana menentukan area dan produk terdampak?","Kapan area boleh dilepas?"],"response":["Hentikan aktivitas dan isolasi area sesuai brittle-material procedure.","Tahan produk/material, alat, pakaian, dan lalu lintas yang mungkin membawa pecahan.","Dokumentasikan lokasi dan lakukan cleaning/inspection sesuai metode resmi.","Area dan produk hanya dilepas oleh pihak berwenang setelah bukti memenuhi acceptance criteria."],"lesson":"Breakage response mengendalikan penyebaran; menyapu cepat tanpa isolasi dapat memperluas bahaya."}],"summary":["Empat kelompok bahaya: biologis, kimia, fisik, dan alergen.","Hazard berbeda dari sumber, jalur, kondisi, dan risk.","Bahaya dapat tidak terlihat, tidak berbau, dan tidak terasa.","Satu kejadian dapat memiliki beberapa bahaya sekaligus.","Affected scope awal menggunakan waktu, lot, area, alat, dan aliran material.","Ketidakpastian dikelola dengan hold dan eskalasi—bukan asumsi aman."],"knowledgeCheck":[{"question":"Residu sanitizer pada food-contact surface termasuk bahaya…","options":["Biologis","Kimia","Fisik","Bukan bahaya"],"answer":1,"rationale":"Residu bahan pembersih atau sanitizer yang tidak terkendali merupakan bahaya kimia."},{"question":"Mengapa produk yang tampak normal belum tentu aman?","options":["Warna selalu salah","Bahaya mikroba, kimia, dan alergen dapat tidak terlihat","Semua produk harus dibuang","Visual tidak pernah digunakan"],"answer":1,"rationale":"Observasi visual penting tetapi tidak cukup untuk semua jenis bahaya."},{"question":"Saat status alergen bahan tidak jelas, tindakan yang tepat?","options":["Gunakan sedikit","Cicipi","Hold, lindungi identitas, dan konfirmasi melalui jalur resmi","Campurkan dengan bahan lain"],"answer":2,"rationale":"Status tidak jelas harus dikendalikan agar tidak terjadi cross-contact atau mislabeling."},{"question":"Baut hilang dari alat. Langkah pertama?","options":["Ganti baut dan lanjut","Stop, lindungi produk/area, cari evidence, dan eskalasi","Tunggu complaint","Catat saat audit"],"answer":1,"rationale":"Penggantian alat tidak menyelesaikan potensi affected product dan foreign-body risk."}],"sources":[{"label":"General Principles of Food Hygiene (CXC 1-1969)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/publications/en/"},{"label":"Food safety overview","organization":"WHO","url":"https://www.who.int/southeastasia/health-topics/food-safety"}]},{"objectives":["Menerapkan persyaratan kesehatan pekerja dan higiene tangan.","Menjalankan entry, gowning, dan perpindahan zona sesuai urutan.","Menjelaskan kapan sarung tangan harus diganti.","Melaporkan kondisi kesehatan tanpa melakukan self-clearance."],"sections":[{"title":"Manusia sebagai sumber dan pemutus kontaminasi","paragraphs":["Tangan, kulit, rambut, luka, pakaian, alas kaki, benda pribadi, batuk, bersin, serta penyakit pekerja dapat menjadi jalur kontaminasi. GMP tidak menganggap manusia sebagai ‘masalah’, tetapi merancang perilaku, fasilitas, dan pengawasan agar perpindahan bahaya dapat dicegah.","Higiene personal efektif bila fasilitas tersedia dan mudah digunakan: tempat cuci tangan, sabun, pengering, tempat penyimpanan barang, pakaian kerja bersih, akses terkontrol, dan aturan zonasi yang jelas. Training tanpa fasilitas yang memadai tidak cukup."]},{"title":"Health reporting dan fitness for work","paragraphs":["Gejala seperti muntah, diare, demam dengan kondisi tertentu, penyakit menular yang relevan, atau luka terinfeksi harus dilaporkan sebelum memasuki area. Pekerja tidak boleh menyembunyikan gejala karena kekurangan tenaga atau takut kehilangan target. Pihak yang ditunjuk menentukan restriction, reassignment, exclusion, dan return-to-work berdasarkan prosedur serta nasihat kesehatan yang berlaku.","Laporan kesehatan adalah informasi sensitif. Supervisor harus menjaga kerahasiaan, tidak mendiagnosis, dan tidak mempermalukan pelapor. Tujuannya melindungi konsumen dan pekerja, bukan menghukum."]},{"title":"Cuci tangan, sarung tangan, dan zonasi","paragraphs":["Cuci tangan mengikuti urutan, durasi, dan fasilitas yang ditetapkan. Momen penting mencakup sebelum masuk, setelah toilet atau istirahat, setelah menyentuh ponsel/benda kotor, setelah batuk/bersin, setelah menangani sampah, dan saat berpindah tugas. Hand sanitizer tidak selalu menggantikan cuci tangan.","Sarung tangan adalah penghalang tambahan, bukan tangan yang otomatis bersih. Sarung tangan diganti bila robek, kotor, menyentuh benda non-higienis, berpindah produk/alergen/tugas, atau sesuai frekuensi prosedur. Gowning dan alur orang harus mengikuti zonasi; perlengkapan dari zona rendah tidak dipindah ke zona lebih tinggi tanpa kontrol."]}],"playbook":["SELF-CHECK kondisi kesehatan sebelum berangkat/masuk shift.","REPORT gejala atau luka melalui kanal yang ditetapkan.","ENTER mengikuti urutan penyimpanan barang, gowning, hand hygiene, dan akses zona.","MAINTAIN higiene selama bekerja; ganti glove/PPE saat integritas atau statusnya berubah.","EXIT dan re-enter mengikuti prosedur; jangan memakai perlengkapan terkontaminasi kembali."],"redFlags":["Muntah atau diare sebelum shift","Luka terbuka/terinfeksi","Sarung tangan menyentuh ponsel","Hair cover tidak menutup rambut","Perhiasan/barang pribadi di area","PPE berpindah zona"],"mistakes":[{"title":"Memakai dua sarung tangan untuk menutup higiene buruk","explanation":"Jumlah lapisan tidak menggantikan handwashing, glove change, atau health reporting."},{"title":"Menentukan sendiri tetap fit bekerja","explanation":"Fitness for work ditentukan melalui prosedur oleh pihak yang ditunjuk."},{"title":"Mencuci glove sebagai pengganti mengganti","explanation":"Praktik ini dapat merusak integritas dan menyebarkan kontaminasi kecuali secara spesifik divalidasi dan diizinkan."}],"cases":[{"title":"Lini kekurangan orang","level":"Rutin","situation":"Seorang operator mengalami diare pada malam hari, merasa membaik pagi ini, dan ingin tetap masuk karena dua rekan absen.","facts":["Ada gejala yang wajib dilaporkan.","Operator belum dinilai pihak yang ditunjuk.","Kebutuhan tenaga tinggi."],"prompts":["Kapan laporan dilakukan?","Siapa menentukan penempatan?","Bagaimana supervisor merespons?"],"response":["Operator melapor sebelum memasuki area produksi.","Supervisor menjaga kerahasiaan dan mengikuti fitness-for-work procedure.","Restriction/reassignment/exclusion ditentukan pihak yang ditunjuk, bukan operator sendiri.","Kekurangan tenaga dikelola tanpa mengorbankan persyaratan higiene."],"lesson":"Kebutuhan produksi tidak mengubah kewajiban health reporting."},{"title":"Ponsel di balik glove","level":"Kritis","situation":"Operator menerima panggilan penting, menyentuh ponsel dengan glove, lalu kembali memegang kemasan primer tanpa mengganti glove atau mencuci tangan.","facts":["Ponsel adalah benda non-higienis.","Glove menyentuh kemasan primer.","Affected scope waktu dan produk dapat ditelusuri."],"prompts":["Apa tindakan langsung?","Produk mana yang dilindungi?","Perbaikan sistem apa yang dipertimbangkan?"],"response":["Hentikan aktivitas, lepaskan glove sesuai prosedur, lakukan hand hygiene, dan gunakan glove baru bila diperlukan.","Lindungi produk/material sejak kontak tidak higienis dan laporkan untuk penilaian.","Catat waktu, area, dan affected window.","Periksa aturan ponsel, akses komunikasi darurat, pengawasan, dan pemahaman pekerja."],"lesson":"Glove dapat menjadi kendaraan kontaminasi; statusnya berubah setelah menyentuh benda kotor."}],"summary":["Laporkan gejala sebelum masuk area; jangan self-clearance.","Health information dijaga kerahasiaannya.","Sarung tangan tidak menggantikan cuci tangan.","Ganti glove setelah menyentuh benda kotor, robek, atau berpindah tugas/alergen.","Ikuti urutan gowning dan alur zona.","Fasilitas dan perilaku harus sama-sama mendukung higiene."],"knowledgeCheck":[{"question":"Pekerja mengalami diare sebelum shift. Tindakan pertama?","options":["Memakai dua glove","Melapor sebelum memasuki area","Bekerja sampai istirahat","Minum obat lalu diam"],"answer":1,"rationale":"Gejala harus dilaporkan agar pihak yang ditunjuk dapat menentukan fitness for work."},{"question":"Glove menyentuh ponsel. Apa berikutnya?","options":["Lap dengan kain","Lanjut bila glove terlihat bersih","Lepas sesuai prosedur, cuci tangan, dan ganti glove bila diperlukan","Semprot parfum"],"answer":2,"rationale":"Ponsel dapat mencemari glove; visual bersih tidak membuktikan higiene."},{"question":"Siapa menentukan pekerja boleh kembali ke area setelah sakit?","options":["Pekerja sendiri","Rekan satu tim","Pihak yang ditunjuk sesuai return-to-work procedure","Security tanpa prosedur"],"answer":2,"rationale":"Return to work harus mengikuti penilaian dan kewenangan yang ditetapkan."},{"question":"Pernyataan yang benar tentang hand sanitizer?","options":["Selalu menggantikan cuci tangan","Digunakan sesuai prosedur dan tidak otomatis menggantikan handwashing","Menghilangkan semua alergen","Boleh dipakai pada glove kotor"],"answer":1,"rationale":"Penggunaan sanitizer mengikuti metode resmi; tangan kotor tetap perlu dicuci."}],"sources":[{"label":"Five Keys to Safer Food Manual","organization":"WHO","url":"https://www.who.int/publications/i/item/9789241594639"},{"label":"Employee Health and Personal Hygiene Handbook","organization":"U.S. FDA","url":"https://www.fda.gov/downloads/Food/GuidanceRegulation/RetailFoodProtection/IndustryandRegulatoryAssistanceandTrainingResources/UCM194575.pdf"}]},{"objectives":["Membedakan cleaning, sanitation, inspection, verification, dan release.","Mengidentifikasi parameter chemical yang tidak boleh ditebak.","Mengenali tanda aktivitas hama dan respons yang dilarang.","Menentukan affected area saat hasil pre-operation tidak memenuhi kriteria."],"sections":[{"title":"Cleaning dan sanitation memiliki fungsi berbeda","paragraphs":["Cleaning menghilangkan soil, sisa produk, lemak, protein, mineral, dan material lain dari permukaan. Sanitation menurunkan mikroorganisme ke tingkat yang diterima setelah permukaan cukup bersih. Soil dapat melindungi mikroorganisme atau menonaktifkan sanitizer; karena itu ‘semprot lebih banyak’ bukan pengganti cleaning yang benar.","Urutan aktual mengikuti SSOP/SOP: persiapan dan pengamanan, pembongkaran bila diperlukan, gross-soil removal, cleaning, rinsing bila disyaratkan, inspection, sanitation, waktu kontak, final rinse bila disyaratkan, assembly, verification, dan release. Jangan menggabungkan atau menghilangkan tahap tanpa validasi dan approval."]},{"title":"Chemical dan cleaning tools sebagai kontrol sekaligus bahaya","paragraphs":["Chemical hanya digunakan bila approved, berlabel, tidak kedaluwarsa, dan sesuai konsentrasi, suhu, contact time, metode, compatibility, serta PPE. Jangan mencampur chemical, memindahkan ke botol minuman, atau mengandalkan warna dan bau untuk identifikasi. Alat ukur harus sesuai dan statusnya dapat dipercaya.","Cleaning tools dipisahkan berdasarkan zona atau penggunaan, disimpan bersih dan kering, serta diperiksa integritasnya. Brush yang kehilangan bulu, scraper retak, atau hose yang menyentuh lantai dapat menjadi sumber bahaya baru."]},{"title":"Pest management dimulai dari pencegahan","paragraphs":["Integrated pest management mengutamakan exclusion, housekeeping, waste control, drain, door discipline, incoming inspection, penyimpanan rapi, dan perbaikan celah. Tanda aktivitas dapat berupa droppings, gnaw marks, webbing, serangga, sarang, bau, kemasan rusak, atau aktivitas pada monitoring device.","Pekerja tidak boleh memindahkan trap, menyentuh bait, atau menyemprot pestisida sendiri. Lindungi produk, batasi area, jaga evidence, dan laporkan. Treatment dilakukan oleh personel berwenang dengan perlindungan pangan yang sesuai."]}],"playbook":["PREPARE area, tools, chemical, PPE, dan status equipment.","CLEAN mengikuti urutan dan parameter SSOP.","INSPECT seluruh food-contact dan adjacent area, termasuk dead spot.","SANITIZE dengan identitas, konsentrasi, dan contact time yang benar.","VERIFY menggunakan metode/acceptance criteria yang ditetapkan.","RELEASE hanya oleh pihak berwenang; hasil gagal memicu reclean/investigation sesuai prosedur."],"redFlags":["Chemical tanpa label","Bau/residu tidak biasa","Tool retak atau hilang bagian","Dead spot tidak dibuka","Swab gagal","Droppings/webbing","Trap dipindahkan"],"mistakes":[{"title":"Permukaan mengkilap dianggap tersanitasi","explanation":"Visual tidak membuktikan parameter chemical atau hasil mikrobiologis."},{"title":"Menambah konsentrasi agar lebih kuat","explanation":"Konsentrasi berlebih dapat meninggalkan residu, merusak equipment, atau membahayakan pekerja."},{"title":"Menghapus tanda hama tanpa bukti","explanation":"Evidence dan lokasi diperlukan untuk menentukan sumber, scope, dan tindakan efektif."}],"cases":[{"title":"Bau chemical setelah pre-op","level":"Rutin","situation":"Area terlihat bersih setelah sanitation, tetapi tercium bau chemical tajam dan operator ingin menjalankan rinse cepat tanpa mencatat.","facts":["Visual inspection lulus.","Ada indikasi residu atau parameter tidak sesuai.","Penyebab belum diketahui."],"prompts":["Apakah area dapat release?","Bukti apa yang diperiksa?","Siapa membuat keputusan?"],"response":["Jangan mulai proses dan pertahankan status area.","Periksa chemical identity, dilution record, contact time, rinsing requirement, alat ukur, dan SSOP.","Lakukan tindakan koreksi serta verification ulang sesuai prosedur.","Release oleh pihak berwenang setelah acceptance criteria terpenuhi."],"lesson":"Sinyal abnormal mengalahkan asumsi ‘sudah dibersihkan’."},{"title":"Tanda hama dekat bahan","level":"Kritis","situation":"Ditemukan droppings dan dua karung berlubang di rak bawah. Seorang pekerja memindahkan trap agar area terlihat rapi sebelum audit.","facts":["Ada evidence aktivitas hama.","Integritas kemasan terganggu.","Monitoring device telah dipindahkan.","Material lain berada di sekitar."],"prompts":["Apa affected scope awal?","Apa yang tidak boleh dilakukan?","Evidence dan pihak apa yang diperlukan?"],"response":["Hentikan penggunaan material terkait, isolasi area, dan tahan kemasan terdampak serta material berisiko di sekitarnya.","Jangan membersihkan/membuang evidence atau memindahkan device lebih lanjut sebelum dokumentasi dan arahan.","Catat lokasi, jumlah, lot, kondisi kemasan, aktivitas device, serta housekeeping.","Libatkan Warehouse, Quality, dan pest-control authority untuk assessment dan treatment."],"lesson":"Pest response melindungi produk sekaligus menjaga pola evidence agar sumber dapat dikendalikan."}],"summary":["Cleaning menghilangkan soil; sanitation menurunkan mikroorganisme.","Chemical mengikuti identitas, konsentrasi, suhu, contact time, metode, dan PPE.","Visual bersih belum tentu memenuhi acceptance criteria.","Tool rusak dapat menjadi sumber kontaminasi.","Pest control mengutamakan prevention dan evidence.","Jangan release area setelah verification gagal."],"knowledgeCheck":[{"question":"Mengapa cleaning dilakukan sebelum sanitation?","options":["Agar warna berubah","Soil dapat melindungi mikroorganisme dan mengurangi efektivitas sanitizer","Sanitizer selalu mahal","Agar record lebih panjang"],"answer":1,"rationale":"Permukaan perlu cukup bersih agar sanitation bekerja sebagaimana dirancang."},{"question":"Chemical dipindahkan ke wadah tanpa label. Tindakan?","options":["Tebak dari warna","Gunakan sedikit","Jangan gunakan; isolasi dan laporkan sesuai chemical-control procedure","Campur air"],"answer":2,"rationale":"Identitas chemical tidak boleh ditebak."},{"question":"Swab gagal meskipun visual bersih. Status area?","options":["Release","Tetap tidak release; tindak lanjuti dan verify ulang","Gunakan untuk produk murah","Tutup hasil"],"answer":1,"rationale":"Hasil verification harus ditindaklanjuti sesuai acceptance criteria."},{"question":"Tanda hama ditemukan. Praktik yang benar?","options":["Semprot sendiri","Pindahkan trap","Lindungi produk, jaga evidence, dan eskalasi","Tunggu audit"],"answer":2,"rationale":"Pest response harus terkontrol dan tidak merusak evidence."}],"sources":[{"label":"General Principles of Food Hygiene (CXC 1-1969)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/publications/en/"},{"label":"PerBPOM 22/2021 — Izin Penerapan CPPOB","organization":"BPOM RI","url":"https://jdih.pom.go.id/view/slide/1304/22/2021/06a0fe35df30cece15afd1c19acc5c3f"}]},{"objectives":["Memetakan jalur kontaminasi silang dan allergen cross-contact.","Menerapkan segregasi, scheduling, line clearance, dan label control.","Menjelaskan risiko rework dan shared equipment.","Merespons material atau alat dengan status alergen yang tidak jelas."],"sections":[{"title":"Kontaminasi berpindah melalui sistem","paragraphs":["Kontaminasi silang adalah perpindahan bahaya dari sumber ke produk melalui tangan, glove, alat, trolley, udara, cairan, drain, alas kaki, kemasan, rework, atau alur orang dan material. Cross-contact digunakan khusus untuk perpindahan alergen yang tidak disengaja. Pemanasan yang membunuh mikroorganisme umumnya tidak dapat diandalkan untuk menghilangkan protein alergen.","Kontrol terbaik memutus jalur sebelum bahaya mencapai produk: zoning, physical separation, covered transfer, dedicated tools, controlled airflow, hygienic design, scheduling, validated cleaning, dan line clearance."]},{"title":"Allergen control dari supplier sampai label","paragraphs":["Allergen management dimulai dari approved material dan dokumen pemasok, berlanjut ke receiving, storage, weighing, transfer, production, rework, cleaning, packaging, dan release. Identitas bahan dan label harus selaras; label yang salah dapat mengekspos konsumen meskipun proses fisik terkendali.","Material alergen disimpan dan dipindahkan sesuai segregasi yang ditetapkan. Wadah tetap tertutup dan beridentitas. Tumpahan ditangani dengan alat/metode yang tidak memperluas debu atau cross-contact. Perubahan bahan, supplier, formula, atau artwork masuk change control sebelum digunakan."]},{"title":"Rework, changeover, dan line clearance","paragraphs":["Rework hanya digunakan jika approved, tertelusur, kompatibel dengan produk dan profil alergen, berada dalam batas waktu/jumlah yang ditetapkan, serta dicatat ke batch penerima. Wadah rework tanpa identitas atau status tidak boleh digunakan.","Changeover memerlukan removal/reconciliation material lama, cleaning sesuai metode, pemeriksaan area dan equipment, verifikasi label/artwork/coding, serta release. Line clearance bukan kegiatan kosmetik; satu label lama dapat menimbulkan mislabeling serius."]}],"playbook":["MAP sumber, jalur, dan titik kontak bersama.","SEGREGATE berdasarkan status, identitas, zona, dan profil alergen.","CONTROL schedule, transfer, tools, rework, cleaning, dan line clearance.","VERIFY label, artwork, equipment, dan area sebelum start/changeover.","HOLD dan eskalasi bila identitas atau status alergen tidak jelas."],"redFlags":["Scoop berpindah zona","Wadah tanpa identitas","Debu alergen terbuka","Rework tidak tertelusur","Label lama tertinggal","Urutan produksi berubah tanpa assessment","Cleaning tidak sesuai changeover"],"mistakes":[{"title":"Mengandalkan precautionary label untuk kontrol buruk","explanation":"Pelabelan bukan pengganti pencegahan dan pengendalian cross-contact yang efektif."},{"title":"Mengembalikan alat ke tempatnya lalu lanjut","explanation":"Perlu menilai material/produk yang mungkin sudah terpapar dan melakukan cleaning sesuai prosedur."},{"title":"Menganggap sedikit alergen pasti aman","explanation":"Pekerja tidak boleh menentukan ambang atau disposition sendiri; paparan dapat serius bagi konsumen sensitif."}],"cases":[{"title":"Scoop salah zona","level":"Rutin","situation":"Scoop berwarna untuk bahan alergen ditemukan di area non-alergen setelah tiga batch selesai.","facts":["Waktu perpindahan scoop tidak diketahui.","Tiga batch telah diproduksi.","Shared contact belum dipetakan."],"prompts":["Apa affected window sementara?","Bukti apa yang dicari?","Apa tindakan terhadap scoop dan area?"],"response":["Stop penggunaan area/alat terkait dan tahan batch sejak kondisi terakhir yang dapat dipercaya.","Amankan scoop, record penggunaan, CCTV bila resmi tersedia, schedule, cleaning, dan traceability bahan.","Lakukan cleaning/verification sesuai allergen procedure.","Quality menentukan scope dan disposition berdasarkan evidence."],"lesson":"Mengembalikan scoop tidak menghapus kemungkinan cross-contact yang sudah terjadi."},{"title":"Label lama setelah changeover","level":"Kritis","situation":"Saat changeover dari produk mengandung susu ke produk tanpa deklarasi susu, satu roll label lama dan beberapa kemasan tercetak ditemukan di bawah meja packing setelah produk baru mulai berjalan.","facts":["Profil alergen kedua produk berbeda.","Line clearance dinyatakan selesai.","Produk baru sudah dikemas.","Jumlah label lama belum direkonsiliasi."],"prompts":["Apa risiko utama?","Apa yang ditahan?","Bagaimana menentukan affected scope?"],"response":["Stop packing dan tahan produk baru, packaging material, serta area terkait.","Pisahkan semua label/kemasan dan lakukan reconciliation terhadap issued–used–returned–destroyed.","Periksa line-clearance record, start-up samples, vision/code checks, waktu, dan jumlah output.","Release/disposition hanya setelah identitas label dan affected window dibuktikan."],"lesson":"Mislabeling alergen dapat lebih berbahaya daripada defect visual dan memerlukan containment segera."}],"summary":["Cross-contamination memiliki banyak jalur; cross-contact khusus alergen.","Pemanasan tidak otomatis menghancurkan protein alergen.","Allergen control mencakup supplier hingga label.","Rework wajib approved, kompatibel, dan tertelusur.","Changeover memerlukan cleaning, line clearance, dan label reconciliation.","Status alergen tidak jelas berarti hold dan eskalasi."],"knowledgeCheck":[{"question":"Jalur cross-contact alergen dapat melalui…","options":["Hanya bahan baku","Alat, debu, tangan, rework, shared line, dan label","Hanya udara","Hanya supplier"],"answer":1,"rationale":"Allergen control harus end-to-end karena banyak jalur perpindahan."},{"question":"Mengapa pemanasan tidak dapat selalu menjadi kontrol alergen?","options":["Alergen selalu berupa logam","Protein alergen umumnya tidak dihancurkan secara andal oleh proses yang membunuh mikroba","Label melindungi panas","Suhu tidak pernah digunakan"],"answer":1,"rationale":"Kontrol mikrobiologis tidak otomatis mengendalikan protein alergen."},{"question":"Rework tanpa identitas ditemukan. Tindakan?","options":["Gunakan pada batch sama warna","Hold dan konfirmasi traceability/approval","Campur sedikit","Beri label baru dari ingatan"],"answer":1,"rationale":"Rework harus approved dan tertelusur sebelum digunakan."},{"question":"Label lama ditemukan setelah changeover. Prioritas?","options":["Buang label lalu lanjut","Stop, tahan affected scope, dan lakukan reconciliation","Tunggu complaint","Tutup dengan sticker"],"answer":1,"rationale":"Mislabeling dapat memengaruhi identitas dan deklarasi alergen."}],"sources":[{"label":"Code of Practice on Food Allergen Management (CXC 80-2020)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/sh-proxy/en/?lnk=1&url=https%3A%2F%2Fworkspace.fao.org%2Fsites%2Fcodex%2FStandards%2FCXC+80-2020%2FCXC_080e.pdf"},{"label":"Codex Codes of Practice","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/codes-of-practice/en/"}]},{"objectives":["Melakukan pemeriksaan receiving berbasis identitas, kondisi, status, dan bukti.","Membedakan quarantine, hold, released, rejected, dan returned.","Menerapkan FIFO/FEFO dan persyaratan penyimpanan.","Menangani temperature excursion tanpa menebak disposition."],"sections":[{"title":"Receiving adalah gerbang kontrol","paragraphs":["Receiving memastikan material yang masuk berasal dari sumber yang disetujui, sesuai PO/specification, memiliki identitas dan lot, serta tiba dalam kendaraan dan kondisi yang dapat diterima. Pemeriksaan meliputi item, quantity, lot, tanggal, seal, kebersihan kendaraan, potensi hama, kerusakan, kondisi kemasan, dokumen, dan suhu bila disyaratkan.","Sampling dan keputusan acceptance mengikuti prosedur. Material tidak boleh dianggap released hanya karena dibutuhkan produksi. Ketidaksesuaian dicatat dan material dipisahkan secara fisik atau sistem sampai ada keputusan berwenang."]},{"title":"Status mengendalikan penggunaan","paragraphs":["Quarantine biasanya menunggu pemeriksaan atau keputusan awal; hold mencegah penggunaan selama deviasi/investigasi; released berarti boleh digunakan dalam scope yang disetujui; rejected tidak memenuhi persyaratan; returned memerlukan identitas dan penilaian tersendiri. Istilah final mengikuti sistem Lahans, tetapi prinsipnya sama: status harus jelas, terlindungi, dan selaras antara label fisik serta sistem.","Label status tidak boleh dipindahkan, ditimpa, atau dibuat ulang tanpa kewenangan. Material tanpa status atau dengan konflik status harus diperlakukan sebagai tidak boleh digunakan sampai dikonfirmasi."]},{"title":"Storage, stock rotation, dan environmental control","paragraphs":["Penyimpanan menjaga suhu, kelembapan, ventilasi, jarak dari lantai/dinding, stacking, perlindungan dari cahaya atau bau, compatibility, allergen segregation, pest prevention, dan akses. Produk tidak diletakkan langsung di lantai atau menghalangi inspeksi dan pembersihan.","FIFO memprioritaskan stok yang diterima lebih dulu; FEFO memprioritaskan yang expiry-nya lebih awal. FEFO lebih relevan ketika tanggal kedaluwarsa tidak mengikuti urutan penerimaan. Stock rotation tetap harus mempertimbangkan status—stok hold tidak boleh digunakan hanya karena expiry lebih dekat."]}],"playbook":["MATCH supplier/PO, item, lot, dokumen, dan requirement.","INSPECT kendaraan, seal, hygiene, pest, packaging, quantity, dan suhu bila berlaku.","STATUS material secara jelas dan selaras antara fisik-sistem.","STORE sesuai condition, segregation, stacking, dan access rule.","ROTATE dengan FIFO/FEFO setelah memastikan status released.","ESCALATE excursion, damage, infestation, atau identity mismatch."],"redFlags":["Seal tidak sesuai","Kendaraan kotor/bau","Suhu excursion","Kemasan basah/robek","Lot tidak terbaca","Status fisik dan sistem berbeda","Pallet di lantai","Barang hold dekat released tanpa kontrol"],"mistakes":[{"title":"Visual normal dianggap membatalkan excursion","explanation":"Keamanan atau shelf life dapat terdampak tanpa perubahan visual."},{"title":"FEFO diterapkan tanpa melihat status","explanation":"Hanya material yang berstatus boleh digunakan yang masuk rotasi konsumsi."},{"title":"Relabel status sendiri agar produksi jalan","explanation":"Tindakan ini merusak traceability dan melanggar kewenangan release."}],"cases":[{"title":"Pallet basah saat receiving","level":"Rutin","situation":"Dua pallet bahan datang dengan sudut karton basah. Inner pack tampak utuh dan supplier meminta diterima karena hujan di perjalanan.","facts":["Kerusakan eksternal terlihat.","Sumber air dan lama paparan tidak diketahui.","Material lain dalam kendaraan tampak kering."],"prompts":["Apa yang diperiksa?","Bagaimana segregasi dan pencatatan?","Siapa memutuskan acceptance?"],"response":["Pisahkan pallet terdampak dan cegah masuk ke released stock.","Catat lot, quantity, posisi, kondisi kendaraan/seal, foto resmi, dan kondisi inner pack tanpa merusak evidence.","Periksa specification dan risiko kontaminasi/kemasan.","Acceptance, reinspection, sampling, atau rejection diputus pihak berwenang."],"lesson":"Pernyataan supplier tidak menggantikan pemeriksaan dan bukti."},{"title":"Temperature excursion dalam perjalanan","level":"Kritis","situation":"Data logger menunjukkan suhu di luar persyaratan selama empat jam. Suhu saat tiba sudah kembali normal dan produk tidak berubah secara visual.","facts":["Ada bukti time-temperature excursion.","Kondisi akhir normal.","Durasi diketahui, penyebab belum jelas.","Produk diminta segera dipakai."],"prompts":["Apa status material?","Data apa yang diperlukan?","Mengapa visual tidak cukup?"],"response":["Tahan material dan jangan mengubah logger/record.","Kumpulkan grafik waktu-suhu, specification, rute, seal, set point, kalibrasi, lot, dan riwayat handling.","Lindungi cold chain material lain dan laporkan ke Warehouse, Quality, Procurement/supplier sesuai prosedur.","Disposition berbasis evaluasi pihak berwenang—bukan suhu saat tiba saja."],"lesson":"Produk yang kembali dingin tidak menghapus paparan sebelumnya atau dampaknya."}],"summary":["Receiving memverifikasi identitas, sumber, kondisi, status, dan bukti.","Material tidak otomatis released karena dibutuhkan.","Status fisik dan sistem harus konsisten.","FIFO berdasarkan urutan masuk; FEFO berdasarkan expiry lebih awal.","Rotasi hanya berlaku untuk stok berstatus boleh digunakan.","Excursion ditahan, dicatat, dan dinilai pihak berwenang."],"knowledgeCheck":[{"question":"FEFO berarti…","options":["Barang terbesar dipakai dulu","Expiry paling awal diprioritaskan setelah status dipastikan","Barang terbaru dipakai dulu","Semua hold dipakai dulu"],"answer":1,"rationale":"FEFO mengurangi risiko kedaluwarsa, tetapi tidak mengalahkan status hold."},{"question":"Material tanpa status ditemukan di staging. Tindakan?","options":["Anggap released","Gunakan untuk trial","Segregate/hold dan konfirmasi status melalui jalur resmi","Buat label sendiri"],"answer":2,"rationale":"Ketidakjelasan status harus mencegah penggunaan."},{"question":"Temperature excursion tetapi visual normal. Keputusan?","options":["Terima","Tahan, kumpulkan data, dan minta disposition berwenang","Ganti logger","Campur dengan lot baik"],"answer":1,"rationale":"Visual tidak membuktikan efek time-temperature exposure."},{"question":"Konflik antara status label fisik dan sistem harus…","options":["Mengikuti yang paling menguntungkan","Dikendalikan sebagai tidak boleh digunakan sampai direkonsiliasi","Dihapus keduanya","Diputus forklift driver"],"answer":1,"rationale":"Konflik status adalah red flag traceability dan release."}],"sources":[{"label":"PerBPOM 21/2021 — CPerPOB dan SMKPO","organization":"BPOM RI","url":"https://e-sertifikasi.pom.go.id/assets/uploads/peraturan/3209861fd05f6325b4c28bf895ef6697.pdf"},{"label":"General Principles of Food Hygiene (CXC 1-1969)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/publications/en/"}]},{"objectives":["Mengenali defect kemasan yang dapat memengaruhi keamanan dan mutu.","Menjalankan line clearance, reconciliation, coding, dan label verification.","Merespons breakage, tool/fastener loss, dan alarm detector.","Menentukan affected window berdasarkan titik pemeriksaan terakhir yang dapat dipercaya."],"sections":[{"title":"Kemasan adalah bagian dari sistem perlindungan","paragraphs":["Kemasan primer dan closure melindungi produk dari kontaminasi, kehilangan integritas, dan perubahan kondisi. Defect yang perlu dikenali antara lain bocor, seal lemah, pinhole, delaminasi, retak, deformasi, closure tidak pas, foreign material, print/coding tidak terbaca, serta material yang tidak sesuai item/version.","Tingkat kritis defect mengikuti specification dan risk assessment. Peserta tidak menentukan sendiri bahwa kebocoran kecil aman; produk ditahan dan dinilai oleh fungsi berwenang."]},{"title":"Foreign-body control dan brittle material","paragraphs":["Foreign-body control menggunakan kombinasi preventive maintenance, tool/fastener accountability, screens, filters, magnets, detector, housekeeping, serta brittle-material register. Jika alat hilang bagian atau benda rapuh pecah, affected scope ditentukan dari pemeriksaan terakhir yang dapat dipercaya, lokasi, aliran produk, waktu, dan kemungkinan penyebaran.","Detector atau interlock tidak boleh di-bypass. Challenge check yang gagal atau alarm berulang memerlukan stop, penahanan produk sesuai affected window, pemulihan kontrol, dan evaluasi produk."]},{"title":"Line clearance, label, dan coding","paragraphs":["Line clearance menghilangkan atau mengendalikan produk, material kemasan, label, artwork, dokumen, sample, dan setting dari run sebelumnya. Start-up verification memastikan item, version, lot/date code, print, barcode/vision system, dan sample sesuai approved master.","Reconciliation membandingkan jumlah material issued, used, returned, damaged, dan destroyed untuk menemukan selisih atau mix-up. Coding harus terbaca dan tertelusur. Koreksi manual, perubahan printer setting, atau rework label hanya dilakukan bila prosedur mengizinkan dan ada approval."]}],"playbook":["VERIFY material/version dan line clearance sebelum start.","CHECK integritas seal/closure, coding, print, dan foreign-body controls pada frekuensi resmi.","STOP saat alarm, defect trend, breakage, atau missing part terjadi.","BOUND affected window dari titik pemeriksaan valid terakhir.","HOLD produk/material, jaga evidence, dan lakukan reconciliation.","RELEASE hanya setelah kontrol pulih dan bukti dinilai berwenang."],"redFlags":["Seal bocor berulang","Label dua versi","Code tidak terbaca","Tool/fastener hilang","Challenge check gagal","Brittle material retak","Selisih reconciliation","Interlock di-bypass"],"mistakes":[{"title":"Membuang kemasan defect tanpa identitas","explanation":"Sample defect membantu menentukan pola, waktu, dan penyebab; ikuti evidence handling."},{"title":"Menganggap detector sebagai jaminan mutlak","explanation":"Detection memiliki capability dan limitation; preventive control tetap diperlukan."},{"title":"Hanya mengganti label yang terlihat","explanation":"Mix-up membutuhkan affected-window analysis dan reconciliation, bukan cosmetic correction."}],"cases":[{"title":"Seal bocor sporadis","level":"Rutin","situation":"Tiga pouch bocor ditemukan dalam 20 menit. Operator menaikkan setting sealer tanpa otorisasi dan membuang sample bocor.","facts":["Defect berulang.","Setting berubah tanpa approval.","Sebagian evidence hilang.","Produk selama periode terkait tersedia."],"prompts":["Apa affected scope sementara?","Bukti apa yang masih dapat dikumpulkan?","Apa risiko perubahan setting?"],"response":["Stop dan tahan produk sejak check integritas terakhir yang dapat dipercaya.","Amankan sample tersisa, record setting, suhu/pressure/time bila relevan, maintenance history, material lot, dan output count.","Kembalikan control melalui personel berwenang; jangan menebak parameter.","Verifikasi hasil dan disposition produk sesuai prosedur."],"lesson":"Mengubah setting dapat menutupi gejala sekaligus menciptakan kondisi baru; bukti harus dijaga."},{"title":"Label alergen tercampur","level":"Kritis","situation":"Dua desain label dengan daftar alergen berbeda ditemukan di hopper label. Sebagian produk telah masuk finished-goods staging.","facts":["Ada potensi mislabeling.","Jumlah label tiap versi belum diketahui.","Produk telah meninggalkan line tetapi belum dikirim."],"prompts":["Area dan material apa yang di-hold?","Data apa yang diperlukan?","Bagaimana mencegah shipment?"],"response":["Stop line dan blokir movement/shipment finished goods terkait.","Tahan produk sejak line-clearance/start-up check terakhir yang dapat dipercaya, semua label/material, dan staging terkait.","Lakukan reconciliation, inspect sample/output, periksa vision/code records dan traceability pallet.","Quality/Regulatory menentukan scope, sorting/rework bila diizinkan, dan disposition."],"lesson":"Salah label dapat menjadi insiden food safety ketika deklarasi alergen atau identitas produk salah."}],"summary":["Kemasan melindungi produk dan membawa identitas/traceability.","Defect kecil tidak otomatis aman; gunakan specification dan authority.","Foreign-body control adalah sistem berlapis.","Missing part, breakage, dan alarm menentukan affected window.","Line clearance dan reconciliation mencegah mix-up.","Label/coding salah dapat menjadi risiko food safety, terutama alergen."],"knowledgeCheck":[{"question":"Challenge check detector gagal. Tindakan?","options":["Ulang sampai lulus lalu abaikan","Stop, tahan affected window, pulihkan kontrol, dan evaluasi","Lanjut karena produk normal","Kurangi frekuensi check"],"answer":1,"rationale":"Kegagalan check mempertanyakan kemampuan kontrol selama periode terkait."},{"question":"Tujuan line clearance adalah…","options":["Membersihkan lantai saja","Menghilangkan/mengendalikan sisa produk, material, label, dan dokumen run sebelumnya","Mempercepat shift","Mengganti reconciliation"],"answer":1,"rationale":"Line clearance mencegah mix-up dan kontaminasi saat start/changeover."},{"question":"Affected window biasanya dimulai dari…","options":["Awal tahun","Pemeriksaan terakhir yang dapat dipercaya sebelum kondisi gagal","Saat auditor datang","Produk terakhir saja"],"answer":1,"rationale":"Titik kontrol valid terakhir membantu membatasi scope secara berbasis bukti."},{"question":"Dua versi label ditemukan. Prioritas pertama?","options":["Buang versi lama","Stop, hold produk/material, dan lakukan reconciliation","Tutup dengan sticker","Lanjut sampai roll habis"],"answer":1,"rationale":"Mix-up label harus dikendalikan sebelum produk bergerak lebih jauh."}],"sources":[{"label":"PerBPOM 22/2021 — Izin Penerapan CPPOB","organization":"BPOM RI","url":"https://jdih.pom.go.id/view/slide/1304/22/2021/06a0fe35df30cece15afd1c19acc5c3f"},{"label":"General Principles of Food Hygiene (CXC 1-1969)","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/publications/en/"}]},{"objectives":["Menjelaskan hubungan lot bahan, proses, kemasan, finished goods, dan distribusi.","Menggunakan Stop–Protect–Report–Record untuk deviasi dan complaint.","Membedakan trace, mock recall, withdrawal/recall, dan disposition.","Mengenali food-defense concern serta menjaga data integrity."],"sections":[{"title":"Traceability membangun rantai bukti","paragraphs":["Traceability menghubungkan approved supplier dan material lot dengan receiving, storage, batch proses, monitoring, rework, packaging lot, finished-goods pallet, shipment, dan customer. One step back–one step forward adalah minimum; sistem internal perlu menghubungkan seluruh transformasi dan penggunaan material.","Trace yang baik menghasilkan quantity reconciliation: jumlah masuk, digunakan, tersisa, scrap, WIP, finished goods, stock, dan terdistribusi dapat dijelaskan. Kecepatan penting, tetapi jawaban cepat yang tidak lengkap atau tidak akurat tidak cukup."]},{"title":"Complaint, hold, dan recall governance","paragraphs":["Complaint dengan indikasi sakit, alergen, benda asing, mislabeling, tampering, atau pola berulang harus masuk kanal resmi segera. Frontliner tidak menjanjikan akar masalah, kompensasi, atau keamanan lot tanpa investigasi. Bukti seperti produk, foto, kemasan, lot code, lokasi pembelian, waktu konsumsi, dan gejala dijaga sesuai prosedur.","Keputusan penarikan dan pemusnahan pangan olahan mengikuti ketentuan yang berlaku serta governance perusahaan. PerBPOM 22 Tahun 2025 menggantikan aturan penarikan 2017, sehingga materi operasional harus direview Quality/Legal sebelum go-live. Peserta foundation berperan mengeskalasi, menjaga bukti, dan menjalankan instruksi—bukan mengumumkan recall sendiri."]},{"title":"Food defense dan data integrity","paragraphs":["Food defense berfokus pada kontaminasi atau gangguan yang disengaja. Concern dapat berupa segel rusak tanpa penjelasan, orang tidak berwenang, perilaku menyembunyikan, bahan/chemical hilang, akses abnormal, atau perubahan produk yang tidak konsisten dengan kegagalan biasa. Jangan melakukan konfrontasi; lindungi area, jaga keselamatan, dan gunakan kanal security/food-defense.","Data integrity membuat traceability dapat dipercaya. Catatan harus attributable, legible, contemporaneous, original/true copy, accurate, complete, consistent, enduring, dan available sesuai sistem yang berlaku. Jangan backdate, memakai identitas rekan, menghapus tanpa jejak, atau merekonstruksi angka dari ingatan."]}],"playbook":["RECEIVE complaint/deviasi dan catat fakta tanpa berjanji hasil.","STOP/PROTECT affected product, material, area, record, dan sample.","TRACE backward ke material/supplier dan forward ke stock/shipment/customer.","RECONCILE quantity dan identifikasi gap/unknown.","REPORT ke crisis/Quality/Legal/Security channel sesuai jenis risiko.","EXECUTE keputusan berwenang dan dokumentasikan komunikasi, retrieval, serta effectiveness."],"redFlags":["Lot code tidak terbaca","Quantity tidak balance","Shipment data terputus","Complaint sakit/alergen/benda asing","Tampering atau akses abnormal","Record diubah","Produk hold bergerak","Pola complaint lintas lot"],"mistakes":[{"title":"Menjanjikan recall sebelum keputusan","explanation":"Recall memerlukan assessment dan kewenangan; frontliner harus mencatat serta mengeskalasi."},{"title":"Menganggap satu lot tanpa memeriksa common material","explanation":"Scope dapat melintasi beberapa batch/produk melalui bahan, rework, equipment, atau packaging yang sama."},{"title":"Mengedit record agar balance","explanation":"Gap harus dijelaskan dan diinvestigasi, bukan disembunyikan."}],"cases":[{"title":"Complaint benda asing","level":"Rutin","situation":"Customer mengirim foto serpihan logam dan kode lot yang terbaca. Customer service ingin menjawab bahwa sumber pasti dari rumah konsumen.","facts":["Ada foto dan lot code.","Produk fisik belum diterima.","Sumber belum diketahui.","Lot lain mungkin menggunakan line yang sama."],"prompts":["Informasi apa yang dikumpulkan?","Apa yang tidak boleh dijanjikan?","Bagaimana affected scope awal dibuat?"],"response":["Catat data customer melalui kanal resmi: produk, lot, waktu/tempat beli, kondisi kemasan, foto, penyimpanan, dan availability sample.","Jangan menyimpulkan sumber atau keamanan produk lain.","Eskalasi dan lindungi stock lot terkait; review foreign-body controls, complaint trend, material/equipment commonality, dan distribution data.","Jaga chain of custody bila sample diterima."],"lesson":"Empati kepada customer berjalan bersama bahasa faktual dan perlindungan evidence."},{"title":"Salah label sudah terkirim","level":"Kritis","situation":"Ditemukan produk dengan label yang tidak menyatakan alergen susu. Dua pallet sudah dikirim ke tiga customer dan satu pallet masih di gudang.","facts":["Ada risiko konsumen sensitif.","Distribusi sebagian sudah terjadi.","Quantity dan affected window perlu direkonsiliasi.","Regulasi penarikan berlaku."],"prompts":["Apa tindakan satu jam pertama?","Data minimum apa yang dibutuhkan?","Siapa yang berwenang mengkomunikasikan?"],"response":["Stop shipment dan tahan seluruh stock/related material yang relevan.","Aktifkan escalation/crisis procedure dan trace lot, label version, pallet, customer, quantity, serta waktu shipment.","Reconcile produced–held–shipped–returned–scrapped dan jaga semua evidence.","Quality/Legal/management berwenang menentukan klasifikasi, notifikasi, recall/withdrawal, dan komunikasi eksternal sesuai PerBPOM yang berlaku."],"lesson":"Traceability yang cepat dan quantity reconciliation memungkinkan perlindungan konsumen secara tepat sasaran."}],"summary":["Traceability menghubungkan supplier hingga customer dan seluruh transformasi internal.","Quantity reconciliation membuktikan kelengkapan trace.","Complaint kritis segera masuk kanal resmi; jangan menebak akar masalah.","Stop–Protect–Report–Record berlaku pada deviasi dan complaint.","Recall hanya diputus dan dikomunikasikan oleh pihak berwenang.","PerBPOM 22/2025 adalah rujukan penarikan/pemusnahan yang berlaku.","Food-defense concern dijaga aman tanpa konfrontasi.","Data integrity menentukan apakah keputusan dapat dipercaya."],"knowledgeCheck":[{"question":"Traceability yang lengkap menghubungkan…","options":["Invoice saja","Supplier/material, proses, rework, kemasan, finished goods, dan distribusi","Nama operator saja","Customer complaint saja"],"answer":1,"rationale":"Traceability end-to-end memerlukan hubungan antar lot dan transformasi."},{"question":"Customer melaporkan benda asing. Respons awal?","options":["Menolak klaim","Menjanjikan akar masalah","Catat fakta, jaga bukti, eskalasi, dan lindungi affected stock","Umumkan recall sendiri"],"answer":2,"rationale":"Frontliner harus empatik tetapi tetap faktual dan mengikuti governance."},{"question":"Quantity reconciliation bertujuan…","options":["Menentukan harga","Menjelaskan jumlah produced, stock, shipped, returned, dan scrap","Mengganti traceability","Menghapus selisih"],"answer":1,"rationale":"Reconciliation menunjukkan apakah seluruh produk terdampak telah diperhitungkan."},{"question":"Aturan BPOM tentang penarikan pangan olahan yang berlaku pada 2026 adalah…","options":["PerKBPOM 22/2017","PerBPOM 22/2025","Tidak ada aturan","WHO Five Keys"],"answer":1,"rationale":"PerBPOM 22 Tahun 2025 mencabut aturan tahun 2017 dan mengatur penarikan serta pemusnahan pangan olahan."}],"sources":[{"label":"PerBPOM 22/2025 — Penarikan dan Pemusnahan Pangan Olahan","organization":"BPOM RI","url":"https://jdih.pom.go.id/view/slide/1678/22/2025/2f11a845c4ae101ec3badc739c3690b1"},{"label":"Codex Guidelines — CXG 60 Traceability/Product Tracing","organization":"Codex Alimentarius","url":"https://www.fao.org/fao-who-codexalimentarius/codex-texts/guidelines/en/"}]}],"visuals":[{"eyebrow":"Decision flow","title":"Dari temuan menuju tindakan aman","caption":"Klik setiap tahap untuk melihat keputusan yang dibutuhkan.","nodes":[{"label":"STOP","detail":"Hentikan aktivitas yang dapat memperbesar risiko apabila aman dilakukan.","tone":"orange"},{"label":"PROTECT","detail":"Tahan produk/material terkait, batasi area, dan jaga bukti serta record asli.","tone":"teal"},{"label":"REPORT","detail":"Sampaikan fakta: apa, lokasi, waktu, lot, kondisi, dan tindakan awal.","tone":"blue"},{"label":"RECORD","detail":"Catat secara kontemporer dan follow up sampai pihak berwenang merespons.","tone":"teal"}],"video":{"title":"WHO: Five Keys to Safer Food","description":"Video resmi WHO mengenai perilaku dasar yang mencegah penyakit akibat pangan.","url":"https://www.youtube.com/watch?v=ONkKy68HEIM","source":"World Health Organization","duration":"4 menit"},"jobAidPage":1},{"eyebrow":"Hazard map","title":"Empat bahaya, empat jalur kontrol","caption":"Klik kelompok bahaya untuk melihat contoh dan tindakan awal.","nodes":[{"label":"BIOLOGIS","detail":"Patogen dari manusia, bahan, air, lingkungan, atau time-temperature abuse. Kontrol: hygiene, process, sanitation, dan suhu.","tone":"teal"},{"label":"KIMIA","detail":"Residue chemical, pelumas, pestisida, kontaminan, atau dosis bahan salah. Jangan identifikasi dengan mencium atau mencicipi.","tone":"blue"},{"label":"FISIK","detail":"Kaca, logam, batu, plastik keras, atau bagian alat. Isolasi area dan jaga evidence sebelum cleaning.","tone":"orange"},{"label":"ALERGEN","detail":"Protein alergen dapat berpindah melalui alat, debu, rework, tangan, dan label. Status tidak jelas berarti hold.","tone":"blue"}],"video":{"title":"WHO: Five Keys to Safer Food - versi singkat","description":"Pengantar visual singkat tentang clean, separate, cook, temperature, dan safe materials.","url":"https://www.youtube.com/watch?v=2ZLRWg0cbMQ","source":"World Health Organization","duration":"1 menit"},"jobAidPage":2},{"eyebrow":"Entry sequence","title":"Urutan masuk area higienis","caption":"Urutan dapat disesuaikan dengan zonasi dan SOP Lahans.","nodes":[{"label":"HEALTH","detail":"Lakukan self-check dan laporkan muntah, diare, penyakit relevan, atau luka terinfeksi sebelum masuk.","tone":"orange"},{"label":"STORE","detail":"Simpan ponsel, makanan, obat pribadi, dan barang terlarang pada tempat yang ditetapkan.","tone":"blue"},{"label":"GOWN","detail":"Kenakan hair/beard cover, pakaian, alas kaki, dan PPE sesuai urutan serta zona.","tone":"teal"},{"label":"WASH","detail":"Lakukan handwashing sesuai metode; glove baru digunakan setelah tangan bersih bila diwajibkan.","tone":"teal"}],"video":{"title":"WHO: Five Keys to Safer Food","description":"Gunakan segmen keep clean sebagai pembuka diskusi higiene personal.","url":"https://www.youtube.com/watch?v=ONkKy68HEIM","source":"World Health Organization","duration":"4 menit"},"jobAidPage":3},{"eyebrow":"Pre-operation flow","title":"Bersih belum tentu siap digunakan","caption":"Klik tahap untuk membedakan cleaning, sanitation, verification, dan release.","nodes":[{"label":"CLEAN","detail":"Hilangkan soil dan sisa produk dengan urutan, tool, dan chemical yang telah disetujui.","tone":"blue"},{"label":"INSPECT","detail":"Periksa food-contact surface, dead spot, tool integrity, residue, dan kondisi abnormal.","tone":"teal"},{"label":"SANITIZE","detail":"Gunakan sanitizer dengan identitas, konsentrasi, contact time, suhu, dan metode resmi.","tone":"orange"},{"label":"VERIFY","detail":"Gunakan acceptance criteria yang ditetapkan. Hasil gagal berarti area tetap tidak release.","tone":"teal"}],"jobAidPage":4},{"eyebrow":"Allergen pathway","title":"Putus jalur cross-contact sebelum label","caption":"Pengendalian berjalan dari sumber hingga kemasan akhir.","nodes":[{"label":"SOURCE","detail":"Pastikan bahan, supplier, dokumen, formula, dan profil alergen telah disetujui.","tone":"blue"},{"label":"SEGREGATE","detail":"Pisahkan storage, weighing, transfer, tool, dan alur sesuai risk assessment.","tone":"teal"},{"label":"CHANGEOVER","detail":"Gunakan schedule, cleaning tervalidasi, rework restriction, dan line clearance.","tone":"orange"},{"label":"LABEL","detail":"Verifikasi artwork, deklarasi alergen, coding, dan reconciliation sebelum release.","tone":"blue"}],"jobAidPage":5},{"eyebrow":"Material journey","title":"Dari kendaraan ke released storage","caption":"Material tidak boleh digunakan sebelum identitas, kondisi, dan statusnya jelas.","nodes":[{"label":"MATCH","detail":"Cocokkan approved supplier, PO, item, lot, quantity, dokumen, dan persyaratan.","tone":"blue"},{"label":"INSPECT","detail":"Periksa kendaraan, seal, kebersihan, pest, packaging, damage, serta suhu bila berlaku.","tone":"teal"},{"label":"STATUS","detail":"Quarantine/hold/released/rejected harus jelas dan konsisten antara fisik serta sistem.","tone":"orange"},{"label":"STORE","detail":"Jaga suhu, humidity, stacking, segregation, dan FEFO setelah status released.","tone":"teal"}],"jobAidPage":6},{"eyebrow":"Defect response","title":"Kemasan, label, dan affected window","caption":"Defect kecil tidak otomatis aman; gunakan spesifikasi dan bukti.","nodes":[{"label":"CHECK","detail":"Periksa material/version, seal, closure, print, code, detector, dan start-up sample.","tone":"blue"},{"label":"STOP","detail":"Hentikan saat defect trend, alarm, missing part, breakage, atau mix-up terjadi.","tone":"orange"},{"label":"BOUND","detail":"Tentukan affected window dari check terakhir yang dapat dipercaya dan aliran produk.","tone":"teal"},{"label":"RELEASE","detail":"Pulihkan kontrol, lakukan verification/reconciliation, lalu tunggu disposition berwenang.","tone":"blue"}],"jobAidPage":7},{"eyebrow":"Traceability chain","title":"Satu lot, satu rantai bukti","caption":"Klik tahap untuk melihat data yang harus dapat ditelusuri.","nodes":[{"label":"SUPPLIER","detail":"Approved supplier, incoming material lot, receiving evidence, dan status awal.","tone":"blue"},{"label":"BATCH","detail":"Material usage, process record, monitoring, rework, inspection, dan packaging lot.","tone":"teal"},{"label":"PALLET","detail":"Finished-goods lot, quantity, stock status, warehouse location, dan movement.","tone":"orange"},{"label":"CUSTOMER","detail":"Shipment, customer, quantity, delivery date, return, complaint, dan retrieval status.","tone":"blue"}],"jobAidPage":8}]};
